NEW = {'be:engine/lvb/lvb_core.py': '# backend/app/engine/lvb/lvb_core.py\n#\n# ── LVB_V1_20261023 ── "Tripwire" level-break alerts. PURE decision logic:\n# ── LVB_SL_SPOT_20261029 ── SL is now SPOT POINTS measured from the limit\n# (CE stop: spot <= Upper − SL; PE stop: spot >= Lower + SL), mirroring TP.\n# The old "% of premium" stop survives ONLY for rows created before this\n# change (sl_pts NULL) so a trade opened under it is still managed as sold.\n# no broker, no DB, no clock — every function here is deterministic and is\n# exercised directly by test_lvb.py.\n#\n# The rule (Anbu, 2026-10-23):\n#   * A condition = instrument + Upper and/or Lower spot level, an option\n#     premium band (default ₹150–200), SL and TP in SPOT points measured FROM\n#     THE LIMIT, an EOD time and lots.\n#   * A 5-minute spot candle that CLOSES above Upper buys a CE; one that\n#     closes below Lower buys a PE — but only as a FRESH cross: the previous\n#     5m close must have been on the inside of that level (for the day\'s\n#     first candle, its OPEN is the reference, so a gap open beyond the\n#     level never triggers). An alert created while spot is already beyond\n#     its level therefore waits for spot to come back inside and cross again.\n#   * The option is the weekly contract on that side with the HIGHEST\n#     premium inside the band (= nearest ATM inside the band).\n#   * Exits: spot <= Upper − SL (CE) / spot >= Lower + SL (PE) → SL;\n#     spot >= Upper + TP (CE) / spot <= Lower − TP (PE) → TP; condition\'s EOD\n#     time → EOD. SL is checked before TP on every poll. Exit fills at the\n#     option LTP. Manual square-off any time.\n#   * One trade per condition: only a FILLED entry consumes it (TRIGGERED).\n#     A breakout that cannot be traded (no strike in the band, decision too\n#     late, order failure, breakout candle already past the target) leaves\n#     it ARMED with a note. Conditions are valid for their day only.\n\nfrom __future__ import annotations\n\nimport re\nfrom typing import Dict, Iterable, List, Optional, Tuple\n\nFENCE = "LVB_V1_20261023"\nSTRATEGY_ID = "LVB_V1"\n\nIST = 5 * 3600 + 30 * 60\nSESSION_OPEN_MIN = 9 * 60 + 15\nBAR_S = 300\nEOD_MIN_ALLOWED = 9 * 60 + 20\nEOD_MAX_ALLOWED = 15 * 60 + 20        # below every generic 15:25 sweep\nLOTS_MAX = 20\nLIMIT_MAX_DIST = 0.10                 # a limit > 10 % from spot is a typo, not a level\nTICK = 0.05\n\nINSTRUMENTS: Dict[str, dict] = {\n    "NIFTY": {"exchange": "NFO", "segment": "NFO-OPT", "name": "NIFTY",\n              "index_key": "NSE:NIFTY 50", "index_token": 256265, "step": 50,\n              "tp_default": 50.0, "sl_default": 25.0},\n    "SENSEX": {"exchange": "BFO", "segment": "BFO-OPT", "name": "SENSEX",\n               "index_key": "BSE:SENSEX", "index_token": 265, "step": 100,\n               "tp_default": 150.0, "sl_default": 75.0},\n}\n\nDEFAULTS = {"prem_min": 150.0, "prem_max": 200.0, "eod": "15:15", "lots": 1}\nSL_PTS_MAX = 2000.0\n\n_HM = re.compile(r"^([01]?\\d|2[0-3]):([0-5]\\d)$")\n\n\n# ── time helpers (epoch seconds, IST) ────────────────────────────────────────\ndef minute_of(ts: int) -> int:\n    return ((int(ts) + IST) % 86400) // 60\n\n\ndef day_start_epoch_of(ts: int) -> int:\n    t = int(ts) + IST\n    return t - t % 86400 - IST\n\n\ndef hm_to_min(s) -> Optional[int]:\n    m = _HM.match(str(s or "").strip())\n    return int(m.group(1)) * 60 + int(m.group(2)) if m else None\n\n\ndef min_to_hm(m: Optional[int]) -> Optional[str]:\n    return None if m is None else f"{int(m) // 60:02d}:{int(m) % 60:02d}"\n\n\ndef round_tick(px: float) -> float:\n    return round(round(float(px) / TICK) * TICK, 2)\n\n\n# ── validation ───────────────────────────────────────────────────────────────\ndef _num(v) -> Optional[float]:\n    if v is None or (isinstance(v, str) and not v.strip()):\n        return None\n    return float(v)\n\n\ndef validate_condition(raw: dict, spot: Optional[float] = None) -> Tuple[Optional[dict], Optional[str]]:\n    """Clean a create/edit payload. Returns (clean, None) or (None, error).\n    `spot` (current index LTP, when known) enables the fat-finger guard."""\n    try:\n        inst = str(raw.get("instrument") or "").strip().upper()\n        if inst not in INSTRUMENTS:\n            return None, "instrument must be NIFTY or SENSEX"\n        spec = INSTRUMENTS[inst]\n        upper, lower = _num(raw.get("upper")), _num(raw.get("lower"))\n        if upper is None and lower is None:\n            return None, "give an Upper limit, a Lower limit, or both"\n        for nm, v in (("Upper", upper), ("Lower", lower)):\n            if v is not None and v <= 0:\n                return None, f"{nm} limit must be positive"\n        if upper is not None and lower is not None and upper <= lower:\n            return None, "Upper limit must be above the Lower limit"\n        if spot and spot > 0:\n            for nm, v in (("Upper", upper), ("Lower", lower)):\n                if v is not None and abs(v - spot) / spot > LIMIT_MAX_DIST:\n                    return None, (f"{nm} limit {v:g} is more than {LIMIT_MAX_DIST:.0%} away from "\n                                  f"{inst} {spot:,.2f} — typo?")\n        pmin = _num(raw.get("prem_min"))\n        pmax = _num(raw.get("prem_max"))\n        pmin = DEFAULTS["prem_min"] if pmin is None else pmin\n        pmax = DEFAULTS["prem_max"] if pmax is None else pmax\n        if not (0 < pmin < pmax <= 5000):\n            return None, "premium range needs 0 < Min < Max"\n        sl = _num(raw.get("sl_pts"))\n        sl = spec["sl_default"] if sl is None else sl\n        if not (0 < sl <= SL_PTS_MAX):\n            return None, f"SL spot points must be above 0 (and at most {SL_PTS_MAX:g})"\n        tp = _num(raw.get("tp_pts"))\n        tp = spec["tp_default"] if tp is None else tp\n        if tp < 0:\n            return None, "TP points cannot be negative (0 = no target)"\n        eod_s = str(raw.get("eod") or DEFAULTS["eod"]).strip()\n        eod = hm_to_min(eod_s)\n        if eod is None or not (EOD_MIN_ALLOWED <= eod <= EOD_MAX_ALLOWED):\n            return None, f"EOD time must be HH:MM between {min_to_hm(EOD_MIN_ALLOWED)} and {min_to_hm(EOD_MAX_ALLOWED)}"\n        lots_raw = raw.get("lots")\n        lots = int(float(lots_raw)) if lots_raw not in (None, "") else DEFAULTS["lots"]\n        if not (1 <= lots <= LOTS_MAX):\n            return None, f"lots must be 1–{LOTS_MAX}"\n    except (TypeError, ValueError) as e:\n        return None, f"bad number: {e}"\n    return {"instrument": inst, "upper": upper, "lower": lower, "prem_min": pmin, "prem_max": pmax,\n            "sl_pts": sl, "tp_pts": tp, "eod": min_to_hm(eod), "lots": lots}, None\n\n\n# ── signal ───────────────────────────────────────────────────────────────────\ndef breakout(prev_close: Optional[float], close: float, upper: Optional[float],\n             lower: Optional[float]) -> Optional[str]:\n    """\'CE\' / \'PE\' / None for one closed 5m bar. Fresh cross only: the\n    reference (previous close, or the day\'s first bar\'s open) must be on the\n    inside of the level. Strict > / < on the close; <= / >= on the reference."""\n    if prev_close is None:\n        return None\n    if upper is not None and close > upper and prev_close <= upper:\n        return "CE"\n    if lower is not None and close < lower and prev_close >= lower:\n        return "PE"\n    return None\n\n\ndef reference_for(bars: List[dict], i: int) -> Optional[float]:\n    """Reference price for bar i of TODAY\'s list: previous close, or the\n    first bar\'s own open."""\n    if i <= 0:\n        return float(bars[0]["open"]) if bars else None\n    return float(bars[i - 1]["close"])\n\n\ndef bar_close_ts(bar: dict) -> int:\n    return int(bar["ts"]) + BAR_S\n\n\ndef condition_sees_bar(cond: dict, bar: dict) -> bool:\n    """A condition judges only bars that CLOSE after it was created, and\n    before its own EOD minute."""\n    cts = bar_close_ts(bar)\n    if cts <= int(cond.get("created_at") or 0):\n        return False\n    eod = hm_to_min(cond.get("eod"))\n    return eod is None or minute_of(cts) < eod\n\n\ndef target_spot(side: str, upper: Optional[float], lower: Optional[float], tp_pts: float) -> Optional[float]:\n    if not tp_pts or tp_pts <= 0:\n        return None\n    if side == "CE":\n        return None if upper is None else round(float(upper) + float(tp_pts), 2)\n    return None if lower is None else round(float(lower) - float(tp_pts), 2)\n\n\ndef stop_spot(side: str, upper: Optional[float], lower: Optional[float], sl_pts: Optional[float]) -> Optional[float]:\n    """Spot stop measured from the limit: CE Upper − SL, PE Lower + SL."""\n    if not sl_pts or sl_pts <= 0:\n        return None\n    if side == "CE":\n        return None if upper is None else round(float(upper) - float(sl_pts), 2)\n    return None if lower is None else round(float(lower) + float(sl_pts), 2)\n\n\ndef target_already_past(side: str, spot_close: float, tp_spot: Optional[float]) -> bool:\n    if tp_spot is None:\n        return False\n    return spot_close >= tp_spot if side == "CE" else spot_close <= tp_spot\n\n\ndef sl_price(entry_px: float, sl_pct: float) -> float:\n    """LEGACY (pre-LVB_SL_SPOT) premium stop — kept for rows created before."""\n    return max(TICK, round_tick(float(entry_px) * (1.0 - float(sl_pct) / 100.0)))\n\n\ndef exit_reason(side: str, opt_ltp: Optional[float], spot: Optional[float],\n                sl_opt: Optional[float], tp_spot: Optional[float],\n                sl_spot: Optional[float] = None) -> Optional[str]:\n    """SL before TP (pessimistic). Missing prices never fire an exit.\n    sl_spot = spot stop (current); sl_opt = legacy premium stop."""\n    if spot is not None and spot > 0 and sl_spot is not None:\n        if (side == "CE" and spot <= sl_spot) or (side == "PE" and spot >= sl_spot):\n            return "SL"\n    if opt_ltp is not None and opt_ltp > 0 and sl_opt is not None and opt_ltp <= sl_opt:\n        return "SL"\n    if spot is not None and spot > 0 and tp_spot is not None:\n        if (side == "CE" and spot >= tp_spot) or (side == "PE" and spot <= tp_spot):\n            return "TP"\n    return None\n\n\n# ── option selection ─────────────────────────────────────────────────────────\ndef chain_rows(rows: Iterable[dict], instrument: str, side: str, spot: float, today,\n               n_strikes: int = 20) -> Tuple[Optional[object], List[dict]]:\n    """Nearest listed expiry (>= today) contracts of one side within\n    ±n_strikes steps of spot. rows = instrument-dump dicts (tradingsymbol,\n    instrument_token, name, exchange, segment, instrument_type, strike,\n    expiry (date), lot_size). Returns (expiry, [contract dicts])."""\n    spec = INSTRUMENTS[instrument]\n    band = spec["step"] * n_strikes\n    mine = []\n    for r in rows:\n        if str(r.get("exchange") or "") != spec["exchange"]:\n            continue\n        if str(r.get("segment") or "") != spec["segment"]:\n            continue\n        if str(r.get("name") or "").upper() != spec["name"]:\n            continue\n        if str(r.get("instrument_type") or "") != side:\n            continue\n        exp = r.get("expiry")\n        if exp is None or (hasattr(exp, "__lt__") and exp < today):\n            continue\n        try:\n            k = float(r.get("strike") or 0)\n        except (TypeError, ValueError):\n            continue\n        if k <= 0 or abs(k - spot) > band:\n            continue\n        mine.append(r)\n    if not mine:\n        return None, []\n    expiry = min(r["expiry"] for r in mine)\n    out = [{"sym": str(r["tradingsymbol"]), "token": int(r.get("instrument_token") or 0),\n            "strike": float(r["strike"]), "expiry": expiry, "lot_size": int(float(r.get("lot_size") or 0)),\n            "exchange": spec["exchange"]}\n           for r in mine if r["expiry"] == expiry]\n    out.sort(key=lambda c: c["strike"])\n    return expiry, out\n\n\ndef pick_option(cands: List[dict], ltps: Dict[str, float], pmin: float, pmax: float,\n                spot: float) -> Optional[dict]:\n    """Highest premium inside [pmin, pmax]; tie → nearest ATM."""\n    best = None\n    for c in cands:\n        px = float(ltps.get(c["sym"]) or 0)\n        if px <= 0 or px < pmin or px > pmax:\n            continue\n        key = (px, -abs(c["strike"] - spot))\n        if best is None or key > best[0]:\n            best = (key, dict(c, ltp=px))\n    return None if best is None else best[1]\n\n\ndef describe(cond: dict) -> str:\n    """One-line human summary (alerts, Telegram, audit)."""\n    parts = []\n    tp = float(cond.get("tp_pts") or 0)\n    sl = cond.get("sl_pts")\n    for side, lvl, sign in (("CE", cond.get("upper"), ">"), ("PE", cond.get("lower"), "<")):\n        if lvl is None:\n            continue\n        t = target_spot(side, cond.get("upper"), cond.get("lower"), tp)\n        z = stop_spot(side, cond.get("upper"), cond.get("lower"), sl)\n        bits = ([f"SL {z:g}"] if z is not None else []) + ([f"TP {t:g}"] if t is not None else [])\n        parts.append(f"{side} {sign} {lvl:g}" + (f" ({\', \'.join(bits)})" if bits else ""))\n    stop = (f"SL {float(sl):g} pts" if sl is not None\n            else f"SL {float(cond.get(\'sl_pct\') or 0):g}% (legacy)")\n    return (f"{cond.get(\'instrument\')} " + " | ".join(parts)\n            + f" · ₹{cond.get(\'prem_min\'):g}–{cond.get(\'prem_max\'):g} · {stop}"\n            + f" · EOD {cond.get(\'eod\')} · {cond.get(\'lots\')} lot(s)")\n', 'be:engine/lvb/lvb_repo.py': '# backend/app/engine/lvb/lvb_repo.py\n#\n# ── LVB_V1_20261023 ── persistence for "Tripwire" conditions.\n#\n# ONE table, lvb_conditions: a condition row also carries the one trade it\n# may produce (symbol, fill, SL, spot target, exit). The trade itself is ALSO\n# booked in paper_trades (strategy_name=\'LVB_V1\') so the Trades page,\n# Dashboard, Analytics, EOD card and the PAPER_LIVE shadow book see it with\n# no extra work; paper_trade_id links the two.\n#\n# status: ARMED → TRIGGERED (entry filled; open until exit_ts is set)\n#         ARMED → EXPIRED  (its EOD minute passed, or its day ended)\n#         ARMED → CANCELLED (deleted on the page)\n# A partial UNIQUE index makes "one trade per condition" a database fact.\n#\n# REMOVAL: drop this table (DROP TABLE lvb_conditions) — nothing else reads it.\n#\n# ── LVB_SL_SPOT_20261029 ── SL moved to spot points: new columns sl_pts\n# (the condition\'s input) and sl_spot (the trade\'s spot stop). Existing\n# tables are migrated in place (ALTER TABLE ADD COLUMN, idempotent). sl_pct is\n# kept for old rows only and written as 0 by new inserts (it was NOT NULL).\n\nfrom __future__ import annotations\n\nimport time\nfrom typing import Callable, List, Optional\n\nSCHEMA = """\nCREATE TABLE IF NOT EXISTS lvb_conditions (\n    id              INTEGER PRIMARY KEY AUTOINCREMENT,\n    day             TEXT NOT NULL,                 -- YYYY-MM-DD (IST) the condition is valid for\n    instrument      TEXT NOT NULL,                 -- NIFTY | SENSEX\n    upper           REAL,\n    lower           REAL,\n    prem_min        REAL NOT NULL,\n    prem_max        REAL NOT NULL,\n    sl_pct          REAL NOT NULL DEFAULT 0,       -- LEGACY (% of premium); 0 for new rows\n    sl_pts          REAL,                          -- SL spot points from the limit\n    tp_pts          REAL NOT NULL,\n    eod             TEXT NOT NULL,                 -- HH:MM\n    lots            INTEGER NOT NULL,\n    status          TEXT NOT NULL,                 -- ARMED | TRIGGERED | EXPIRED | CANCELLED\n    created_at      INTEGER NOT NULL,\n    updated_at      INTEGER,\n    note            TEXT,                          -- last engine note (skipped breakout etc.)\n    -- the trade (TRIGGERED only)\n    side            TEXT,                          -- CE | PE\n    trigger_bar_ts  INTEGER,                       -- 5m bar start epoch\n    trigger_close   REAL,\n    mode            TEXT,                          -- PAPER | LIVE (the book it was taken in)\n    symbol          TEXT,\n    token           INTEGER,\n    exchange        TEXT,\n    expiry          TEXT,\n    strike          REAL,\n    lot_size        INTEGER,\n    qty             INTEGER,\n    entry_ts        INTEGER,\n    entry_px        REAL,\n    entry_spot      REAL,\n    sl_px           REAL,                          -- LEGACY premium stop (old rows only)\n    sl_spot         REAL,                          -- spot stop: Upper − SL / Lower + SL\n    tp_spot         REAL,\n    paper_trade_id  TEXT,\n    exit_ts         INTEGER,\n    exit_px         REAL,\n    exit_spot       REAL,\n    exit_reason     TEXT,                          -- SL | TP | EOD | MANUAL | KILL | BROKER_FLAT | STALE\n    mark            REAL,                          -- last polled option LTP (panel)\n    mark_spot       REAL\n);\nCREATE INDEX IF NOT EXISTS lvb_conditions_day ON lvb_conditions(day, status);\n"""\n\nMIGRATE_COLS = (("sl_pts", "REAL"), ("sl_spot", "REAL"))   # ── LVB_SL_SPOT_20261029 ──\nCOLS = ("id", "day", "instrument", "upper", "lower", "prem_min", "prem_max", "sl_pct", "sl_pts", "tp_pts", "eod",\n        "lots", "status", "created_at", "updated_at", "note", "side", "trigger_bar_ts", "trigger_close",\n        "mode", "symbol", "token", "exchange", "expiry", "strike", "lot_size", "qty", "entry_ts",\n        "entry_px", "entry_spot", "sl_px", "sl_spot", "tp_spot", "paper_trade_id", "exit_ts", "exit_px",\n        "exit_spot", "exit_reason", "mark", "mark_spot")\nEDITABLE = ("upper", "lower", "prem_min", "prem_max", "sl_pts", "tp_pts", "eod", "lots", "instrument")\n\n\nclass LvbRepo:\n    def __init__(self, conn_fn: Optional[Callable] = None, clock: Callable[[], float] = time.time):\n        if conn_fn is None:\n            from app.db.sqlite import get_conn as conn_fn          # thread-local, autocommit\n        self._conn_fn = conn_fn\n        self.clock = clock\n        self._ready = False\n\n    def conn(self):\n        c = self._conn_fn()\n        if not self._ready:\n            c.executescript(SCHEMA)\n            have = {r[1] for r in c.execute("PRAGMA table_info(lvb_conditions)").fetchall()}\n            for col, typ in MIGRATE_COLS:            # ── LVB_SL_SPOT_20261029 ── in-place, idempotent\n                if col not in have:\n                    c.execute(f"ALTER TABLE lvb_conditions ADD COLUMN {col} {typ}")\n            self._ready = True\n        return c\n\n    @staticmethod\n    def _row(cur, r) -> dict:\n        return dict(zip([d[0] for d in cur.description], tuple(r)))\n\n    def _all(self, sql: str, args=()) -> List[dict]:\n        cur = self.conn().execute(sql, args)\n        return [self._row(cur, r) for r in cur.fetchall()]\n\n    # ── reads ──\n    def get(self, cid: int) -> Optional[dict]:\n        rows = self._all("SELECT * FROM lvb_conditions WHERE id=?", (int(cid),))\n        return rows[0] if rows else None\n\n    def for_day(self, day: str) -> List[dict]:\n        return self._all("SELECT * FROM lvb_conditions WHERE day=? ORDER BY id", (day,))\n\n    def armed(self, day: str) -> List[dict]:\n        return self._all("SELECT * FROM lvb_conditions WHERE day=? AND status=\'ARMED\' ORDER BY id", (day,))\n\n    def open_trades(self) -> List[dict]:\n        """Every TRIGGERED row without an exit (any day — the engine closes a\n        prior day\'s as STALE)."""\n        return self._all("SELECT * FROM lvb_conditions WHERE status=\'TRIGGERED\' AND exit_ts IS NULL ORDER BY id")\n\n    def recent_closed(self, limit: int = 30) -> List[dict]:\n        return self._all("SELECT * FROM lvb_conditions WHERE status=\'TRIGGERED\' AND exit_ts IS NOT NULL "\n                         "ORDER BY exit_ts DESC LIMIT ?", (int(limit),))\n\n    # ── writes ──\n    def create(self, day: str, c: dict) -> int:\n        now = int(self.clock())\n        cur = self.conn().execute(\n            "INSERT INTO lvb_conditions (day, instrument, upper, lower, prem_min, prem_max, sl_pct, sl_pts, tp_pts,"\n            " eod, lots, status, created_at, updated_at) VALUES (?,?,?,?,?,?,0,?,?,?,?, \'ARMED\', ?, ?)",\n            (day, c["instrument"], c.get("upper"), c.get("lower"), c["prem_min"], c["prem_max"], c["sl_pts"],\n             c["tp_pts"], c["eod"], int(c["lots"]), now, now))\n        return int(cur.lastrowid)\n\n    def update_armed(self, cid: int, c: dict) -> bool:\n        """Edit an ARMED condition. created_at is RESET: a changed level is a\n        new alert, so bars that closed before the edit are never judged\n        against it (fresh-cross rule)."""\n        now = int(self.clock())\n        sets = ", ".join(f"{k}=?" for k in EDITABLE)\n        cur = self.conn().execute(\n            f"UPDATE lvb_conditions SET {sets}, created_at=?, updated_at=?, note=NULL WHERE id=? AND status=\'ARMED\'",\n            tuple(c.get(k) for k in EDITABLE) + (now, now, int(cid)))\n        return cur.rowcount == 1\n\n    def set_status(self, cid: int, status: str, note: Optional[str] = None, only_if: str = "ARMED") -> bool:\n        cur = self.conn().execute(\n            "UPDATE lvb_conditions SET status=?, note=COALESCE(?, note), updated_at=? WHERE id=? AND status=?",\n            (status, note, int(self.clock()), int(cid), only_if))\n        return cur.rowcount == 1\n\n    def note(self, cid: int, text: str) -> None:\n        self.conn().execute("UPDATE lvb_conditions SET note=?, updated_at=? WHERE id=?",\n                            (text, int(self.clock()), int(cid)))\n\n    def mark_triggered(self, cid: int, t: dict) -> bool:\n        """ARMED → TRIGGERED with the filled trade. Guarded on ARMED so a\n        condition can never carry two trades."""\n        cur = self.conn().execute(\n            "UPDATE lvb_conditions SET status=\'TRIGGERED\', side=?, trigger_bar_ts=?, trigger_close=?, mode=?,"\n            " symbol=?, token=?, exchange=?, expiry=?, strike=?, lot_size=?, qty=?, entry_ts=?, entry_px=?,"\n            " entry_spot=?, sl_px=?, sl_spot=?, tp_spot=?, paper_trade_id=?, mark=?, mark_spot=?, note=?, updated_at=?"\n            " WHERE id=? AND status=\'ARMED\'",\n            (t["side"], t.get("trigger_bar_ts"), t.get("trigger_close"), t["mode"], t["symbol"], t.get("token"),\n             t.get("exchange"), str(t.get("expiry") or "") or None, t.get("strike"), t.get("lot_size"), t["qty"],\n             t["entry_ts"], t["entry_px"], t.get("entry_spot"), t.get("sl_px"), t.get("sl_spot"), t.get("tp_spot"),\n             t.get("paper_trade_id"), t["entry_px"], t.get("entry_spot"), t.get("note"), int(self.clock()),\n             int(cid)))\n        return cur.rowcount == 1\n\n    def mark_exit(self, cid: int, exit_px: float, reason: str, exit_spot: Optional[float]) -> None:\n        now = int(self.clock())\n        self.conn().execute(\n            "UPDATE lvb_conditions SET exit_ts=?, exit_px=?, exit_reason=?, exit_spot=?, mark=?, updated_at=?"\n            " WHERE id=? AND exit_ts IS NULL", (now, float(exit_px), reason, exit_spot, float(exit_px), now, int(cid)))\n\n    def set_marks(self, cid: int, mark: Optional[float], mark_spot: Optional[float]) -> None:\n        self.conn().execute("UPDATE lvb_conditions SET mark=COALESCE(?, mark), mark_spot=COALESCE(?, mark_spot)"\n                            " WHERE id=?", (mark, mark_spot, int(cid)))\n\n    def expire_before(self, day: str) -> int:\n        """ARMED conditions of earlier days → EXPIRED (valid for their day only)."""\n        cur = self.conn().execute(\n            "UPDATE lvb_conditions SET status=\'EXPIRED\', note=COALESCE(note, \'day ended\'), updated_at=?"\n            " WHERE status=\'ARMED\' AND day < ?", (int(self.clock()), day))\n        return cur.rowcount\n', 'be:engine/lvb/lvb_manager.py': '# backend/app/engine/lvb/lvb_manager.py\n#\n# ── LVB_V1_20261023 ── orders + persistence for "Tripwire".\n#\n# Cloned from EmcManager (the fleet\'s newest single-long-option donor) and\n# widened from ONE position to MANY (one per condition, keyed by condition\n# id). Same day-1 doctrines:\n#   * any degraded persistence import REFUSES new entries (never trade from\n#     memory);\n#   * LIVE exits are reconcile-first: never sell without a positive holdings\n#     read; unreadable broker → back off and retry, never guess;\n#   * generic paper_trades rows (PAPER / LIVE; PAPER_LIVE twins are booked\n#     by the shadow book inside paper_trades_repo).\n#   * NO GTT / broker-side stop: SL, TP and EOD are ENGINE exits while the\n#     app runs (ORB / VET / EMC doctrine). If the app is down there is no\n#     stop at the broker — the LIVE EOD backstop job and MIS do not cover a\n#     NRML long either; this is in the Settings/page copy.\n#\n# ── LVB_SL_SPOT_20261029 ── the stop is on SPOT (p.sl_spot, from the limit);\n# p.sl (premium stop) is set only for trades opened before that change.\n#\n# Thread safety: the engine thread (polls) and the API threads (manual\n# square-off, kill switch) both close positions → one RLock around every\n# open/close.\n\nfrom __future__ import annotations\n\nimport threading\nimport time\nimport uuid\nfrom typing import Callable, Dict, List, Optional\n\nfrom app.engine.lvb.lvb_core import (STRATEGY_ID, INSTRUMENTS, exit_reason, hm_to_min, sl_price,\n                                     day_start_epoch_of, stop_spot)\n\ntry:\n    from app.risk import execution_modes as _xm\nexcept Exception:                                          # standalone tests\n    class _xm:                                             # type: ignore\n        @staticmethod\n        def normalize(raw, default="PAPER"):\n            m = str(raw or default).strip().upper().replace("+", "_").replace(" ", "_")\n            return m if m in ("OFF", "PAPER", "LIVE", "PAPER_LIVE") else default\n\nFILL_TIMEOUT_S = 20\nFILL_POLL_S = 1.0\nZERODHA_EXECUTOR = "ZerodhaOrderExecutor"     # the only executor with BFO (SENSEX) routing\n\n_DEGRADED: List[str] = []\n\ntry:\n    from app.event_bus.audit_logger import write_audit_log\nexcept ImportError:\n    _DEGRADED.append("audit_logger")\n    def write_audit_log(msg):                              # type: ignore\n        print(msg)\n\ntry:\n    from app.event_bus.inapp_events import record_alert\nexcept ImportError:\n    _DEGRADED.append("inapp_events")\n    def record_alert(*a, **k):                             # type: ignore\n        print("ALERT", a, k)\n\ntry:\n    from app.db.paper_trades_repo import insert_paper_trade, close_paper_trade\nexcept ImportError:\n    _DEGRADED.append("paper_trades_repo")\n    insert_paper_trade = close_paper_trade = None          # type: ignore\n\ntry:\n    from app.config.strategy_loader import load_strategy_config\nexcept ImportError:\n    _DEGRADED.append("strategy_loader")\n    load_strategy_config = None                            # type: ignore\n\ntry:\n    from app.backtest.charges.charges_model import charges_for_long_trade\nexcept ImportError:\n    charges_for_long_trade = None                          # type: ignore   # net shown gross-only\n\n\nclass LvbPosition:\n    def __init__(self, **k):\n        self.__dict__.update(k)\n\n    def view(self) -> dict:\n        return {k: getattr(self, k, None) for k in (\n            "cid", "row_id", "instrument", "symbol", "exchange", "side", "mode", "entry_px", "qty", "lots",\n            "sl", "sl_spot", "tp_spot", "eod", "entry_ts", "entry_spot", "mark", "mark_spot")}\n\n\nclass LvbManager:\n    def __init__(self, repo, executor=None, *, cfg_fn: Optional[Callable] = None, notifier=None,\n                 clock: Callable[[], float] = time.time, sleep: Callable[[float], None] = time.sleep):\n        self.repo = repo\n        self.executor = executor\n        self.cfg_fn = cfg_fn\n        self.notifier = notifier\n        self.clock = clock\n        self.sleep = sleep\n        self.pos: Dict[int, LvbPosition] = {}\n        self.lock = threading.RLock()\n        self._allow_degraded = False              # tests only — never set live\n        self._backoff: Dict[int, tuple] = {}      # cid -> (n, until)\n\n    # ── config / mode ──\n    def cfg(self) -> dict:\n        if self.cfg_fn:\n            return self.cfg_fn() or {}\n        if load_strategy_config is None:\n            return {}\n        try:\n            return load_strategy_config(STRATEGY_ID) or {}\n        except Exception:\n            return {}\n\n    def raw_mode(self) -> str:\n        return _xm.normalize(self.cfg().get("trade_execution_mode", "PAPER"))\n\n    def mode(self) -> str:\n        m = self.raw_mode()\n        return "LIVE" if m == "PAPER_LIVE" else m          # twin booked by paper_trades_repo\n\n    def attach_executor(self, executor) -> None:\n        self.executor = executor\n\n    # ── helpers ──\n    def net_of(self, entry: float, exit_px: float, qty: int) -> float:\n        ch = 0.0\n        if charges_for_long_trade is not None:\n            try:\n                ch = charges_for_long_trade(entry_price=float(entry), exit_price=float(exit_px),\n                                            qty=int(qty)).total_charges\n            except Exception:\n                ch = 0.0\n        return round((float(exit_px) - float(entry)) * int(qty) - ch, 2)\n\n    def _alert(self, code, msg, severity="warning", mode=None):\n        write_audit_log(f"[LVB][{code}] {msg}")\n        try:\n            record_alert(code, msg, severity=severity, strategy_id=STRATEGY_ID,\n                         mode=str(mode or self.mode() or "paper").lower())\n        except Exception:\n            pass\n\n    def _notify(self, fn_name, payload):\n        target = self.notifier\n        if target is None:\n            try:\n                from app.api import telegram_api as target\n            except Exception:\n                return\n        try:\n            getattr(target, fn_name)(payload)\n        except Exception as e:\n            write_audit_log(f"[LVB][NOTIFY_FAIL] {fn_name}: {e!r}")\n\n    # ── entry ──\n    def open_position(self, cond: dict, pick: dict, *, side: str, trigger_bar_ts: int, trigger_close: float,\n                      tp_spot: Optional[float], entry_spot: Optional[float]) -> Optional[float]:\n        """Buy the picked contract for condition `cond`. Returns the fill\n        price, or None when nothing was opened (every refusal is alerted and\n        noted on the condition; it stays ARMED)."""\n        cid = int(cond["id"])\n        with self.lock:\n            if _DEGRADED and not self._allow_degraded:\n                self._alert("PERSIST_DOWN", f"degraded imports {_DEGRADED} — REFUSING to trade", "critical")\n                return None\n            if cid in self.pos:\n                self._alert("DOUBLE_ENTRY", f"#{cid} refused — it already holds a position", "error")\n                return None\n            mode = self.mode()\n            if mode == "OFF":\n                self.repo.note(cid, f"{side} breakout at {trigger_close:g} ignored — strategy is OFF")\n                write_audit_log(f"[LVB][MODE_OFF] #{cid} {side} {pick[\'sym\']} entry ignored")\n                return None\n            lot_size = int(pick.get("lot_size") or 0)\n            if lot_size <= 0:\n                self._refuse(cid, "NO_LOT_SIZE", f"{pick[\'sym\']}: lot size unknown — entry forfeited")\n                return None\n            lots = int(cond["lots"])\n            qty = lots * lot_size\n            sym, token, exch = pick["sym"], int(pick.get("token") or 0), pick.get("exchange") or "NFO"\n            if mode == "LIVE":\n                fill_px = self._live_buy(cid, sym, token, qty, exch)\n                if fill_px is None:\n                    return None\n            else:\n                ltp = float(pick.get("ltp") or 0)\n                if ltp <= 0:\n                    self._refuse(cid, "NO_QUOTE", f"{sym}: no LTP for the paper fill — entry forfeited")\n                    return None\n                fill_px = ltp\n            fill_px = round(float(fill_px), 2)\n            if cond.get("sl_pts") is not None:      # ── LVB_SL_SPOT_20261029 ── spot stop from the limit\n                sl, sl_spot = None, stop_spot(side, cond.get("upper"), cond.get("lower"), float(cond["sl_pts"]))\n            else:                                   # legacy row (created before the change)\n                sl, sl_spot = sl_price(fill_px, float(cond.get("sl_pct") or 30)), None\n            entry_ts = int(self.clock())\n            pid = None\n            if insert_paper_trade is not None:\n                try:\n                    pid = str(uuid.uuid4())\n                    insert_paper_trade(\n                        paper_trade_id=pid, strategy_name=STRATEGY_ID, trade_mode=mode, symbol=sym, token=token,\n                        side=side, entry_price=fill_px, candle_ts=int(trigger_bar_ts),\n                        sl_price=float(sl or 0.0),   # spot stop lives in lvb_conditions.sl_spot — never a premium\n                        tp_price=0.0,        # the target is on SPOT (lvb_conditions.tp_spot) — never an option price\n                        rr=0.0, lots=lots, lot_size=lot_size, qty=qty, trade_direction="LONG",\n                        group_id=f"LVB:{cid}", trade_class=None)\n                except Exception as e:\n                    self._alert("ROW_FAIL", f"#{cid} {sym}: {e!r}"\n                                + (" — POSITION OPEN AT BROKER, paper_trades row missing" if mode == "LIVE" else ""),\n                                "critical" if mode == "LIVE" else "error")\n                    pid = None\n            note = f"{side} on the {_hm(trigger_bar_ts + 300)} close {trigger_close:g}"\n            ok = self.repo.mark_triggered(cid, {\n                "side": side, "trigger_bar_ts": int(trigger_bar_ts), "trigger_close": float(trigger_close),\n                "mode": mode, "symbol": sym, "token": token, "exchange": exch, "expiry": pick.get("expiry"),\n                "strike": pick.get("strike"), "lot_size": lot_size, "qty": qty, "entry_ts": entry_ts,\n                "entry_px": fill_px, "entry_spot": entry_spot, "sl_px": sl, "sl_spot": sl_spot, "tp_spot": tp_spot,\n                "paper_trade_id": pid, "note": note})\n            if not ok:\n                self._alert("COND_ROW_FAIL", f"#{cid} could not be marked TRIGGERED (no longer ARMED?) — "\n                            f"{sym} position is tracked in memory only; square it off manually",\n                            "critical" if mode == "LIVE" else "error")\n            self.pos[cid] = LvbPosition(\n                cid=cid, row_id=pid, instrument=cond["instrument"], symbol=sym, token=token, exchange=exch,\n                side=side, mode=mode, entry_px=fill_px, qty=qty, lots=lots, sl=sl, sl_spot=sl_spot, tp_spot=tp_spot,\n                eod=cond["eod"], eod_min=hm_to_min(cond["eod"]), entry_ts=entry_ts, entry_spot=entry_spot,\n                mark=fill_px, mark_spot=entry_spot)\n            write_audit_log(f"[LVB][ENTRY][{mode}] #{cid} {side} {sym} @ {fill_px} qty={qty} "\n                            f"SLspot={sl_spot} SLprem={sl} TPspot={tp_spot} {note}")\n            self._notify("notify_trade_entry", {\n                "strategy_id": STRATEGY_ID, "mode": mode, "symbol": sym, "side": side, "entry_price": fill_px,\n                "quantity": qty, "sl": sl, "tp": None,   # spot levels are in the note, never as ₹\n                "note": (f"Tripwire #{cid} · {cond[\'instrument\']} 5m close {trigger_close:g} "\n                         f"{\'above\' if side == \'CE\' else \'below\'} {cond[\'upper\'] if side == \'CE\' else cond[\'lower\']:g}"\n                         + (f" · SL spot {sl_spot:g}" if sl_spot is not None else f" · SL ₹{sl:g} (legacy %)")\n                         + (f" · TP spot {tp_spot:g}" if tp_spot is not None else " · no target")\n                         + f" · EOD {cond[\'eod\']}")})\n            return fill_px\n\n    def _refuse(self, cid: int, code: str, msg: str, severity: str = "error"):\n        self._alert(code, f"#{cid} {msg}", severity)\n        try:\n            self.repo.note(cid, f"{code}: {msg} — still armed")\n        except Exception:\n            pass\n\n    def _live_buy(self, cid: int, sym: str, token: int, qty: int, exch: str) -> Optional[float]:\n        ex = self.executor\n        if ex is None:\n            self._refuse(cid, "NO_EXECUTOR", "LIVE entry impossible — executor missing; entry forfeited")\n            return None\n        required = ("place_buy", "place_market_sell", "get_order_fill", "get_open_positions_or_none")\n        missing = [m for m in required if not callable(getattr(ex, m, None))]\n        if missing:\n            self._refuse(cid, "EXEC_CONTRACT", f"LIVE blocked — executor missing {missing}; ZERO orders placed")\n            return None\n        if exch != "NFO" and type(ex).__name__ != ZERODHA_EXECUTOR:\n            self._refuse(cid, "EXCHANGE_UNSUPPORTED", f"{sym} is a {exch} contract; the bound executor "\n                         f"({type(ex).__name__}) routes NFO only — ZERO orders placed")\n            return None\n        try:\n            order_id, avg, filled = ex.place_buy(sym, int(token or 0), int(qty))\n        except Exception as e:\n            self._refuse(cid, "BUY_FAIL", f"{sym}: {e!r}")\n            return None\n        fill_px, ok = float(avg or 0.0), bool(filled == qty and avg)\n        t0 = self.clock()\n        while not ok and self.clock() - t0 < FILL_TIMEOUT_S:\n            self.sleep(FILL_POLL_S)\n            try:\n                st = ex.get_order_fill(order_id)\n            except Exception:\n                continue\n            status = (st or {}).get("status")\n            if status == "COMPLETE":\n                fill_px, ok = float(st.get("avg_price") or 0.0), True\n            elif status in ("REJECTED", "CANCELLED") and (st or {}).get("found"):\n                self._refuse(cid, "BUY_DEAD", f"{sym} order {status} {(st or {}).get(\'status_message\') or \'\'}".strip())\n                return None\n        if not ok or fill_px <= 0:\n            self._alert("FILL_TIMEOUT", f"#{cid} {sym} unfilled after {FILL_TIMEOUT_S}s — abandoning (CHECK THE "\n                        "BROKER: a late fill would be an untracked position)", "critical", mode="LIVE")\n            try:\n                self.repo.note(cid, f"FILL_TIMEOUT {sym} — check the broker; condition still armed")\n            except Exception:\n                pass\n            return None\n        return fill_px\n\n    # ── exits ──\n    def check(self, cid: int, opt_ltp: Optional[float], spot: Optional[float]) -> Optional[str]:\n        """One poll for one position: update marks, take SL/TP. Returns the\n        exit reason when it closed."""\n        with self.lock:\n            p = self.pos.get(cid)\n            if p is None:\n                return None\n            if opt_ltp and opt_ltp > 0:\n                p.mark = float(opt_ltp)\n            if spot and spot > 0:\n                p.mark_spot = float(spot)\n            reason = exit_reason(p.side, opt_ltp, spot, p.sl, p.tp_spot, getattr(p, "sl_spot", None))\n            if reason is None:\n                return None\n            return reason if self.close(cid, reason, ltp=opt_ltp, spot=spot) is not None else None\n\n    def close(self, cid: int, reason: str, ltp: Optional[float] = None, spot: Optional[float] = None) -> Optional[float]:\n        """Close one position. Returns the exit price, or None when nothing\n        was closed (no position, or LIVE backoff — retried by the engine)."""\n        with self.lock:\n            p = self.pos.get(cid)\n            if p is None:\n                return None\n            px = float(ltp if ltp else (p.mark or p.entry_px))\n            if p.mode == "LIVE" and self.executor is not None:\n                n, until = self._backoff.get(cid, (0, 0.0))\n                if self.clock() < until:\n                    return None\n                probe = getattr(self.executor, "get_open_positions_or_none", None)\n                if callable(probe):\n                    try:\n                        positions = probe()\n                    except Exception:\n                        positions = None\n                    if positions is None:\n                        n += 1\n                        self._backoff[cid] = (n, self.clock() + min(60.0, 5.0 * n))\n                        self._alert("BROKER_UNREADABLE", f"#{cid} {p.symbol}: holdings read failed — NO order placed, "\n                                    f"backoff {min(60, 5 * n)}s", "error", mode="LIVE")\n                        return None\n                    holding = any((q.get("tradingsymbol") or q.get("symbol")) == p.symbol\n                                  and int(q.get("quantity") or q.get("qty") or 0) > 0 for q in positions)\n                    if not holding:\n                        self._alert("BROKER_FLAT", f"#{cid} {p.symbol}: broker shows no holding — closing the ROW "\n                                    "only, placing NOTHING (reconcile-first)", "warning", mode="LIVE")\n                        return self._finish(p, px, "BROKER_FLAT", spot)\n                self._backoff.pop(cid, None)\n                try:\n                    order_id = self.executor.place_market_sell(p.symbol, p.qty)\n                    t0 = self.clock()\n                    while self.clock() - t0 < FILL_TIMEOUT_S:\n                        try:\n                            st = self.executor.get_order_fill(order_id)\n                        except Exception:\n                            self.sleep(FILL_POLL_S)\n                            continue\n                        if (st or {}).get("status") == "COMPLETE":\n                            px = float(st.get("avg_price") or px)\n                            break\n                        self.sleep(FILL_POLL_S)\n                except Exception as e:\n                    n += 1\n                    self._backoff[cid] = (n, self.clock() + min(60.0, 5.0 * n))\n                    self._alert("SELL_FAIL", f"#{cid} {p.symbol}: {e!r} — POSITION STILL OPEN AT THE BROKER, "\n                                f"retrying in {min(60, 5 * n)}s", "critical", mode="LIVE")\n                    return None\n            return self._finish(p, px, reason, spot)\n\n    def _finish(self, p: LvbPosition, px: float, reason: str, spot: Optional[float]) -> float:\n        px = round(float(px), 2)\n        if close_paper_trade is not None and p.row_id:\n            try:\n                close_paper_trade(paper_trade_id=p.row_id, exit_price=px, exit_reason=reason)\n            except Exception as e:\n                self._alert("CLOSE_ROW_FAIL", f"#{p.cid} {p.symbol}: {e!r}", "error")\n        try:\n            self.repo.mark_exit(p.cid, px, reason, spot if spot else p.mark_spot)\n        except Exception as e:\n            self._alert("COND_EXIT_FAIL", f"#{p.cid}: {e!r}", "error")\n        gross = (px - p.entry_px) * p.qty\n        write_audit_log(f"[LVB][EXIT][{p.mode}] #{p.cid} {reason} {p.symbol} @ {px} gross={gross:,.0f}")\n        fn = {"SL": "notify_sl_exit", "TP": "notify_tp_exit"}.get(reason, "notify_manual_exit")\n        self._notify(fn, {"strategy_id": STRATEGY_ID, "mode": p.mode, "symbol": p.symbol, "side": p.side,\n                          "entry_price": p.entry_px, "exit_price": px, "quantity": p.qty, "pnl": round(gross, 2),\n                          "exit_reason": reason, "reason": reason})\n        self.pos.pop(p.cid, None)\n        self._backoff.pop(p.cid, None)\n        return px\n\n    def close_all(self, reason: str, ltps: Optional[Dict[int, float]] = None) -> int:\n        n = 0\n        for cid in list(self.pos):\n            if self.close(cid, reason, ltp=(ltps or {}).get(cid)) is not None:\n                n += 1\n        return n\n\n    # ── restart ──\n    def resume(self, now: int) -> int:\n        """Adopt today\'s open trades from lvb_conditions; a prior day\'s open\n        trade is closed STALE at entry (intraday strategy — the app died\n        before its EOD) with a critical alert to verify the broker."""\n        today0 = day_start_epoch_of(now)\n        n = 0\n        for r in self.repo.open_trades():\n            cid = int(r["id"])\n            if cid in self.pos:\n                continue\n            if day_start_epoch_of(int(r.get("entry_ts") or 0)) != today0:\n                if close_paper_trade is not None and r.get("paper_trade_id"):\n                    try:\n                        close_paper_trade(paper_trade_id=r["paper_trade_id"], exit_price=float(r["entry_px"]),\n                                          exit_reason="STALE")\n                    except Exception as e:\n                        self._alert("STALE_FAIL", f"#{cid}: {e!r}", "error")\n                self.repo.mark_exit(cid, float(r["entry_px"]), "STALE", None)\n                self._alert("STALE_ROW", f"#{cid} {r.get(\'symbol\')} ({r.get(\'mode\')}) open since {r.get(\'day\')} — "\n                            "closed as STALE at entry. VERIFY THE BROKER BOOK.", "critical", mode=r.get("mode"))\n                continue\n            self.pos[cid] = LvbPosition(\n                cid=cid, row_id=r.get("paper_trade_id"), instrument=r["instrument"], symbol=r["symbol"],\n                token=int(r.get("token") or 0), exchange=r.get("exchange") or INSTRUMENTS[r["instrument"]]["exchange"],\n                side=r["side"], mode=str(r.get("mode") or "PAPER").upper(), entry_px=float(r["entry_px"]),\n                qty=int(r["qty"]), lots=int(r.get("lots") or 1), sl=r.get("sl_px"), sl_spot=r.get("sl_spot"),\n                tp_spot=r.get("tp_spot"),\n                eod=r["eod"], eod_min=hm_to_min(r["eod"]), entry_ts=int(r["entry_ts"]), entry_spot=r.get("entry_spot"),\n                mark=r.get("mark") or float(r["entry_px"]), mark_spot=r.get("mark_spot"))\n            n += 1\n            write_audit_log(f"[LVB][RESUME] #{cid} {r[\'side\']} {r[\'symbol\']} @ {r[\'entry_px\']} ({r.get(\'mode\')}) "\n                            f"SLspot={r.get(\'sl_spot\')} SLprem={r.get(\'sl_px\')} TPspot={r.get(\'tp_spot\')} EOD {r[\'eod\']}")\n        return n\n\n    # ── kill switch ──\n    def kill_all(self) -> int:\n        n = self.close_all("KILL")\n        write_audit_log(f"[LVB][KILL] flattened {n} position(s)")\n        return n\n\n    def kill_adapter(self) -> dict:\n        """kill_switch contract: {"closed", "remaining", "detail"}."""\n        n = self.kill_all()\n        left = [p.symbol for p in self.pos.values()]\n        return {"closed": n, "remaining": len(left),\n                "detail": [f"LVB_V1 closed {n}"] + ([f"still open: {\', \'.join(left)}"] if left else [])}\n\n    def positions(self) -> List[dict]:\n        with self.lock:\n            return [p.view() for p in self.pos.values()]\n\n\ndef _hm(ts: int) -> str:\n    m = ((int(ts) + 19800) % 86400) // 60\n    return f"{m // 60:02d}:{m % 60:02d}"\n', 'be:engine/lvb/test_lvb.py': '# backend/app/engine/lvb/test_lvb.py\n#\n# ── LVB_V1_20261023 ── behavioural suite for "Tripwire". Standalone:\n#   cd backend && PYTHONPATH=$PWD python3 app/engine/lvb/test_lvb.py\n# Real LvbEngine + LvbManager + LvbRepo (sqlite :memory:) driven by a fake\n# Kite on the REAL epoch clock (IST session times as true epoch seconds —\n# TSG_BANK_FIX1 real-clock rule), plus the pure core functions.\nimport os\nimport sqlite3\nimport sys\nimport tempfile\nfrom datetime import date, datetime, timedelta, timezone\n\nos.environ.setdefault("SCALP_APP_HOME", tempfile.mkdtemp(prefix="lvb_test_"))\n\nfrom app.engine.lvb import lvb_core as core                       # noqa: E402\nfrom app.engine.lvb import lvb_manager as M                       # noqa: E402\nfrom app.engine.lvb import lvb_engine as E                        # noqa: E402\nfrom app.engine.lvb.lvb_repo import LvbRepo                       # noqa: E402\n\nTZ = timezone(timedelta(hours=5, minutes=30))\nDAY = date(2026, 10, 27)                       # a Tuesday (NIFTY weekly expiry)\nNEXT = date(2026, 11, 3)\nDS = int(datetime(DAY.year, DAY.month, DAY.day, tzinfo=TZ).timestamp())\nFAILS = []\nLOG = []\n\n\ndef check(name, cond, extra=""):\n    print(f"   {\'PASS\' if cond else \'FAIL\'}  {name}" + (f"   [{extra}]" if (extra and not cond) else ""))\n    if not cond:\n        FAILS.append(name)\n\n\ndef T(h, m, s=0, day_offset=0):\n    return DS + day_offset * 86400 + h * 3600 + m * 60 + s\n\n\ndef bar_ts(h, m):\n    return T(h, m)\n\n\n# ── fakes ────────────────────────────────────────────────────────────────────\nclass Clock:\n    def __init__(self, t): self.t = t\n    def __call__(self): return self.t\n\n\nclass FakeKite:\n    """historical_data over scripted 5m bars; ltp over a mutable price dict."""\n    def __init__(self, clock):\n        self.clock = clock\n        self.bars = {256265: [], 265: []}      # token -> [(ts, o, h, l, c)]\n        self.px = {}                            # \'NFO:SYM\' / \'NSE:NIFTY 50\' -> price\n        self.calls = {"hist": 0, "ltp": 0}\n\n    def historical_data(self, instrument_token, from_date, to_date, interval):\n        assert interval == "5minute"\n        self.calls["hist"] += 1\n        out = []\n        for ts, o, h, l, c in self.bars[int(instrument_token)]:\n            if ts <= self.clock():               # Kite also returns the bar in progress\n                out.append({"date": datetime.fromtimestamp(ts, TZ), "open": o, "high": h, "low": l, "close": c})\n        return out\n\n    def ltp(self, keys):\n        self.calls["ltp"] += 1\n        return {k: {"last_price": self.px[k]} for k in keys if self.px.get(k)}\n\n\ndef rows():\n    out = []\n    tok = 900000\n    for inst, exch, seg, base, step, lot, exps in (\n            ("NIFTY", "NFO", "NFO-OPT", 25000, 50, 65, (DAY, NEXT)),\n            ("SENSEX", "BFO", "BFO-OPT", 82000, 100, 20, (date(2026, 10, 29), date(2026, 11, 5)))):\n        for exp in exps + (DAY - timedelta(days=7),):       # an expired week must be ignored\n            for i in range(-25, 26):\n                k = base + i * step\n                for t in ("CE", "PE"):\n                    tok += 1\n                    out.append({"tradingsymbol": f"{inst}{exp:%y%m%d}{k}{t}", "instrument_token": tok, "name": inst,\n                                "exchange": exch, "segment": seg, "instrument_type": t, "strike": float(k),\n                                "expiry": exp, "lot_size": lot})\n    return out\n\n\nROWS = rows()\n\n\ndef sym(inst, k, t, exp=DAY):\n    return f"{inst}{exp:%y%m%d}{k}{t}"\n\n\ndef set_chain(kite, inst="NIFTY", exp=DAY, prices=None, exch="NFO"):\n    """Default NIFTY chain: CE 24950=205, 25000=180, 25050=160, 25100=140 …"""\n    for r in ROWS:\n        if r["name"] != inst or r["expiry"] != exp:\n            continue\n        kite.px[f"{exch}:{r[\'tradingsymbol\']}"] = 0\n    for (k, t), v in (prices or {}).items():\n        kite.px[f"{exch}:{sym(inst, k, t, exp)}"] = v\n\n\nNIFTY_CE = {(24950, "CE"): 205, (25000, "CE"): 180, (25050, "CE"): 160, (25100, "CE"): 140}\nNIFTY_PE = {(24850, "PE"): 210, (24800, "PE"): 190, (24750, "PE"): 165, (24700, "PE"): 120}\n\n\nclass Recorder:\n    def __init__(self):\n        self.inserts, self.closes, self.alerts, self.notes = [], [], [], []\n\n    def insert(self, **k): self.inserts.append(k)\n    def close(self, **k): self.closes.append(k)\n    def alert(self, code, msg, **k): self.alerts.append((code, msg, k))\n\n\nclass Notifier:\n    def __init__(self): self.sent = []\n    def __getattr__(self, name):\n        return lambda payload: self.sent.append((name, payload))\n\n\nclass FakeExec:\n    def __init__(self, name="ZerodhaOrderExecutor"):\n        self.__class__ = type(name, (FakeExec,), {})\n        self.orders, self.positions_result, self.fill = [], [], 181.0\n        self.sell_fill = None\n\n    def place_buy(self, symbol, token, qty):\n        self.orders.append(("BUY", symbol, qty))\n        self.positions_result = [{"tradingsymbol": symbol, "quantity": qty}]\n        return "OID-B", 0.0, qty\n\n    def place_market_sell(self, symbol, qty):\n        self.orders.append(("SELL", symbol, qty))\n        return "OID-S"\n\n    def get_order_fill(self, oid):\n        if oid == "OID-B":\n            return {"status": "COMPLETE", "avg_price": self.fill, "found": True}\n        return {"status": "COMPLETE", "avg_price": self.sell_fill or 0, "found": True}\n\n    def get_open_positions_or_none(self):\n        return self.positions_result\n\n\ndef harness(mode="PAPER", start=T(9, 0), conn=None, executor=None):\n    clock = Clock(start)\n    kite = FakeKite(clock)\n    conn = conn or _mem()\n    repo = LvbRepo(conn_fn=lambda: conn, clock=clock)\n    rec = Recorder()\n    M.insert_paper_trade, M.close_paper_trade, M.record_alert = rec.insert, rec.close, rec.alert\n    M.write_audit_log = E.write_audit_log = LOG.append\n    cfg = {"trade_execution_mode": mode}\n    mgr = M.LvbManager(repo, executor=executor, cfg_fn=lambda: cfg, notifier=Notifier(), clock=clock,\n                       sleep=lambda s: setattr(clock, "t", clock.t + s))\n    mgr._allow_degraded = True\n    feed = E.LvbFeed(lambda: kite, rows_fn=lambda: ROWS)\n    eng = E.LvbEngine(mgr, repo, feed=feed, clock=clock, sleep=lambda s: None, trading_day_fn=lambda d: True)\n    return clock, kite, repo, mgr, eng, rec, cfg\n\n\ndef _mem():\n    c = sqlite3.connect(":memory:", isolation_level=None)\n    c.row_factory = sqlite3.Row\n    return c\n\n\ndef run(eng, clock, until, step=1):\n    while clock.t < until:\n        eng.tick(clock.t)\n        clock.t += step\n    eng.tick(clock.t)\n\n\ndef addbar(kite, h, m, o, c, token=256265, hi=None, lo=None):\n    kite.bars[token].append((bar_ts(h, m), o, hi or max(o, c), lo or min(o, c), c))\n\n\ndef cond(repo, clock, **k):\n    base = {"instrument": "NIFTY", "upper": 25000, "lower": 24800}\n    base.update(k)\n    clean, err = core.validate_condition(base)\n    assert not err, err\n    return repo.create(DAY.isoformat(), clean)\n\n\n# ── core ─────────────────────────────────────────────────────────────────────\ndef test_core():\n    print("core")\n    c, e = core.validate_condition({"instrument": "nifty", "upper": "25000"})\n    check("C1 defaults: band 150–200, NIFTY SL 25 pts, NIFTY TP 50, EOD 15:15, 1 lot",\n          e is None and c["prem_min"] == 150 and c["prem_max"] == 200 and c["sl_pts"] == 25 and c["tp_pts"] == 50\n          and c["eod"] == "15:15" and c["lots"] == 1 and c["lower"] is None, e)\n    c, e = core.validate_condition({"instrument": "SENSEX", "lower": 81000})\n    check("C2 SENSEX defaults: TP 150, SL 75 pts", e is None and c["tp_pts"] == 150 and c["sl_pts"] == 75, e)\n    check("C2b SL 0 / negative refused (a stop is mandatory)",\n          core.validate_condition({"instrument": "NIFTY", "upper": 1, "sl_pts": 0})[1] is not None\n          and core.validate_condition({"instrument": "NIFTY", "upper": 1, "sl_pts": -5})[1] is not None)\n    check("C3 neither limit → error", core.validate_condition({"instrument": "NIFTY"})[1] is not None)\n    check("C4 upper ≤ lower → error",\n          core.validate_condition({"instrument": "NIFTY", "upper": 24800, "lower": 24800})[1] is not None)\n    check("C5 fat-finger: 2500 vs spot 25000 refused",\n          core.validate_condition({"instrument": "NIFTY", "upper": 2500}, spot=25000)[1] is not None)\n    check("C6 EOD 15:25 refused (above 15:20), 09:19 refused",\n          core.validate_condition({"instrument": "NIFTY", "upper": 1, "eod": "15:25"})[1] is not None\n          and core.validate_condition({"instrument": "NIFTY", "upper": 1, "eod": "09:19"})[1] is not None)\n    check("C7 lots 0 and 21 refused",\n          core.validate_condition({"instrument": "NIFTY", "upper": 1, "lots": 0})[1] is not None\n          and core.validate_condition({"instrument": "NIFTY", "upper": 1, "lots": 21})[1] is not None)\n    check("C8 TP 0 allowed (no target)", core.validate_condition({"instrument": "NIFTY", "upper": 1, "tp_pts": 0})[0]\n          ["tp_pts"] == 0)\n    b = core.breakout\n    check("C9 fresh cross up → CE; prev beyond → None; close == level → None",\n          b(24990, 25010, 25000, None) == "CE" and b(25005, 25010, 25000, None) is None\n          and b(24990, 25000, 25000, None) is None)\n    check("C10 prev exactly AT the level counts as inside", b(25000, 25001, 25000, None) == "CE")\n    check("C11 PE mirror", b(24810, 24790, None, 24800) == "PE" and b(24795, 24790, None, 24800) is None)\n    bars = [{"ts": 0, "open": 25020, "close": 25030}, {"ts": 300, "open": 25030, "close": 25040}]\n    check("C12 first bar\'s reference is its OPEN (gap open beyond the level never triggers)",\n          core.reference_for(bars, 0) == 25020 and b(core.reference_for(bars, 0), 25030, 25000, None) is None)\n    check("C13 TP measured from the LIMIT: 25000+50, 24800−50; tp 0 → None",\n          core.target_spot("CE", 25000, 24800, 50) == 25050 and core.target_spot("PE", 25000, 24800, 50) == 24750\n          and core.target_spot("CE", 25000, None, 0) is None)\n    check("C14 spot stop measured from the LIMIT: CE 25000−25 = 24975, PE 24800+25 = 24825",\n          core.stop_spot("CE", 25000, 24800, 25) == 24975 and core.stop_spot("PE", 25000, 24800, 25) == 24825)\n    check("C15 spot SL: CE spot ≤ stop, PE spot ≥ stop; TP otherwise; missing prices never exit",\n          core.exit_reason("CE", 150, 24975, None, 25050, 24975) == "SL"\n          and core.exit_reason("CE", 150, 24976, None, 25050, 24975) is None\n          and core.exit_reason("PE", 150, 24825, None, 24750, 24825) == "SL"\n          and core.exit_reason("CE", 150, 25060, None, 25050, 24975) == "TP"\n          and core.exit_reason("PE", 150, 24740, None, 24750, 24825) == "TP"\n          and core.exit_reason("CE", None, None, None, 25050, 24975) is None)\n    check("C15b legacy premium stop still honoured for old rows (sl_spot None)",\n          core.exit_reason("CE", 120, 25010, 126.7, 25050, None) == "SL" and core.sl_price(181.0, 30) == 126.7)\n    exp, cands = core.chain_rows(ROWS, "NIFTY", "CE", 25000, DAY)\n    check("C16 chain: nearest listed expiry (expiry day itself), CE only, ±20 strikes",\n          exp == DAY and cands and all(x["sym"].endswith("CE") for x in cands) and len(cands) == 41)\n    exp, cands = core.chain_rows(ROWS, "SENSEX", "PE", 82000, DAY)\n    check("C17 SENSEX chain = BFO, lot 20, expiry 29-Oct", exp == date(2026, 10, 29) and cands[0]["exchange"] == "BFO"\n          and cands[0]["lot_size"] == 20)\n    ltps = {sym("NIFTY", k, t): v for (k, t), v in NIFTY_CE.items()}\n    exp, cands = core.chain_rows(ROWS, "NIFTY", "CE", 25010, DAY)\n    p = core.pick_option(cands, ltps, 150, 200, 25010)\n    check("C18 pick = highest premium inside ₹150–200 (25000CE @180, not 24950 @205)",\n          p and p["strike"] == 25000 and p["ltp"] == 180)\n    check("C19 nothing in band → None", core.pick_option(cands, ltps, 300, 400, 25010) is None)\n\n\n# ── engine scenarios ─────────────────────────────────────────────────────────\ndef test_paper_ce_tp():\n    print("paper — CE breakout → TP on spot")\n    clock, kite, repo, mgr, eng, rec, _ = harness()\n    cid = cond(repo, clock)\n    set_chain(kite, prices=NIFTY_CE)\n    addbar(kite, 9, 15, 24960, 24990)\n    addbar(kite, 9, 20, 24990, 25012)                    # closes 09:25 above 25000 → CE\n    run(eng, clock, T(9, 25, 4))\n    check("E1 nothing before the 09:25 bar has settled", not mgr.pos)\n    run(eng, clock, T(9, 25, 7))\n    r = repo.get(cid)\n    check("E2 CE bought on the 09:25 close: 25000CE @180, qty 65", r["status"] == "TRIGGERED"\n          and r["symbol"] == sym("NIFTY", 25000, "CE") and r["entry_px"] == 180 and r["qty"] == 65, r and r["status"])\n    check("E3 SL spot 24975 (limit − 25), TP spot 25050 (limit + 50), no premium stop",\n          r["sl_spot"] == 24975 and r["tp_spot"] == 25050 and r["sl_px"] is None, (r["sl_spot"], r["sl_px"]))\n    check("E4 paper_trades row: LVB_V1 PAPER, sl_price 0 and tp_price 0 (spot levels never stored as premiums)",\n          rec.inserts and rec.inserts[0]["strategy_name"] == "LVB_V1" and rec.inserts[0]["trade_mode"] == "PAPER"\n          and rec.inserts[0]["tp_price"] == 0.0 and rec.inserts[0]["sl_price"] == 0.0)\n    kite.px["NSE:NIFTY 50"] = 25040\n    kite.px[f"NFO:{sym(\'NIFTY\', 25000, \'CE\')}"] = 200\n    run(eng, clock, T(9, 40))\n    check("E5 spot 25040 < 25050 → still open", cid in mgr.pos)\n    kite.px["NSE:NIFTY 50"] = 25051\n    kite.px[f"NFO:{sym(\'NIFTY\', 25000, \'CE\')}"] = 214\n    run(eng, clock, T(9, 40, 4))\n    r = repo.get(cid)\n    check("E6 spot 25051 ≥ 25050 → TP at the option LTP 214", r["exit_reason"] == "TP" and r["exit_px"] == 214\n          and rec.closes and rec.closes[-1]["exit_reason"] == "TP")\n    addbar(kite, 9, 25, 25012, 24990)\n    addbar(kite, 9, 30, 24990, 25020)                     # a second fresh cross\n    run(eng, clock, T(9, 40, 30))\n    check("E7 one trade per condition: a later fresh cross does nothing", len(rec.inserts) == 1)\n\n\ndef test_gap_and_fresh_cross():\n    print("gap open / alert created while already beyond")\n    clock, kite, repo, mgr, eng, rec, _ = harness()\n    cid = cond(repo, clock)\n    set_chain(kite, prices=NIFTY_CE)\n    addbar(kite, 9, 15, 25020, 25030)                     # gap OPEN above 25000\n    addbar(kite, 9, 20, 25030, 25045)\n    run(eng, clock, T(9, 30, 10))\n    check("G1 gap open beyond the level → no trade", not rec.inserts and repo.get(cid)["status"] == "ARMED")\n    addbar(kite, 9, 25, 25045, 24995)                     # back inside\n    addbar(kite, 9, 30, 24995, 25008)                     # fresh cross\n    run(eng, clock, T(9, 35, 10))\n    check("G2 comes back inside, crosses again → CE", len(rec.inserts) == 1)\n\n    clock, kite, repo, mgr, eng, rec, _ = harness(start=T(10, 2))\n    set_chain(kite, prices=NIFTY_CE)\n    t = 9 * 60 + 15\n    while t < 10 * 60 + 5:                                # spot above 25000 all morning\n        addbar(kite, t // 60, t % 60, 25010, 25020)\n        t += 5\n    cid = cond(repo, clock)                               # created 10:02, spot already beyond\n    addbar(kite, 10, 0, 25020, 25030)\n    run(eng, clock, T(10, 5, 10))\n    check("G3 alert created while beyond → waits (no trade)", not rec.inserts)\n    addbar(kite, 10, 5, 25030, 24980)\n    addbar(kite, 10, 10, 24980, 25004)\n    run(eng, clock, T(10, 15, 10))\n    check("G4 … then trades the next fresh cross", len(rec.inserts) == 1 and repo.get(cid)["status"] == "TRIGGERED")\n\n\ndef test_pe_sl_eod():\n    print("PE breakout → SL; another → EOD")\n    clock, kite, repo, mgr, eng, rec, _ = harness()\n    a = cond(repo, clock, upper=None, lower=24800)\n    b = cond(repo, clock, upper=None, lower=24800, eod="11:00", sl_pts=60)\n    set_chain(kite, prices=NIFTY_PE)\n    addbar(kite, 9, 15, 24830, 24810)\n    addbar(kite, 9, 20, 24810, 24790)\n    run(eng, clock, T(9, 25, 7))\n    ra, rb = repo.get(a), repo.get(b)\n    check("P1 both conditions trade the same bar (each its own trade) — 24800PE @190",\n          ra["status"] == rb["status"] == "TRIGGERED" and ra["symbol"] == sym("NIFTY", 24800, "PE")\n          and ra["entry_px"] == 190 and len(rec.inserts) == 2)\n    check("P2 TP spot = Lower − 50 = 24750; SL spot A = Lower + 25 = 24825, B = Lower + 60 = 24860",\n          ra["tp_spot"] == 24750 and ra["sl_spot"] == 24825 and rb["sl_spot"] == 24860)\n    kite.px["NSE:NIFTY 50"] = 24824\n    kite.px[f"NFO:{sym(\'NIFTY\', 24800, \'PE\')}"] = 168\n    run(eng, clock, T(9, 29))\n    check("P3a spot 24824 < A\'s stop 24825 → both still open", a in mgr.pos and b in mgr.pos)\n    kite.px["NSE:NIFTY 50"] = 24826\n    kite.px[f"NFO:{sym(\'NIFTY\', 24800, \'PE\')}"] = 163\n    run(eng, clock, T(9, 30))\n    check("P3 spot 24826 ≥ 24825 → A stops out at the option LTP 163; B (stop 24860) holds",\n          repo.get(a)["exit_reason"] == "SL" and repo.get(a)["exit_px"] == 163 and b in mgr.pos)\n    kite.px[f"NFO:{sym(\'NIFTY\', 24800, \'PE\')}"] = 150\n    run(eng, clock, T(10, 59, 58))\n    check("P4 B still open at 10:59", b in mgr.pos)\n    run(eng, clock, T(11, 0, 3))\n    check("P5 B squared off at its own EOD 11:00 @150", repo.get(b)["exit_reason"] == "EOD"\n          and repo.get(b)["exit_px"] == 150)\n\n\ndef test_skips_stay_armed():\n    print("untradeable breakouts leave the condition ARMED")\n    clock, kite, repo, mgr, eng, rec, _ = harness()\n    cid = cond(repo, clock, prem_min=300, prem_max=400)\n    set_chain(kite, prices=NIFTY_CE)\n    addbar(kite, 9, 15, 24960, 24990)\n    addbar(kite, 9, 20, 24990, 25012)\n    run(eng, clock, T(9, 25, 8))\n    r = repo.get(cid)\n    check("S1 no strike in ₹300–400 → ARMED with a NO_STRIKE note", r["status"] == "ARMED"\n          and "NO_STRIKE" in (r["note"] or ""), r["note"])\n\n    clock, kite, repo, mgr, eng, rec, _ = harness()\n    cid = cond(repo, clock, tp_pts=10)\n    set_chain(kite, prices=NIFTY_CE)\n    addbar(kite, 9, 15, 24960, 24990)\n    addbar(kite, 9, 20, 24990, 25015)                     # close 25015 ≥ target 25010\n    run(eng, clock, T(9, 25, 8))\n    check("S2 breakout candle already past the spot target → not traded, ARMED",\n          not rec.inserts and repo.get(cid)["status"] == "ARMED" and "target" in (repo.get(cid)["note"] or ""))\n\n    clock, kite, repo, mgr, eng, rec, cfg = harness(mode="OFF")\n    cid = cond(repo, clock)\n    set_chain(kite, prices=NIFTY_CE)\n    addbar(kite, 9, 15, 24960, 24990)\n    addbar(kite, 9, 20, 24990, 25012)\n    run(eng, clock, T(9, 25, 8))\n    check("S3 mode OFF → breakout ignored, noted, ARMED", not rec.inserts and repo.get(cid)["status"] == "ARMED"\n          and "OFF" in (repo.get(cid)["note"] or ""))\n\n\ndef test_late_and_expiry():\n    print("restart late / EOD expiry")\n    clock, kite, repo, mgr, eng, rec, _ = harness(start=T(10, 30))\n    conn_cid = None\n    set_chain(kite, prices=NIFTY_CE)\n    cid = repo.create(DAY.isoformat(), core.validate_condition({"instrument": "NIFTY", "upper": 25000})[0])\n    repo.conn().execute("UPDATE lvb_conditions SET created_at=? WHERE id=?", (T(9, 0), cid))\n    addbar(kite, 9, 15, 24960, 24990)\n    addbar(kite, 9, 20, 24990, 25012)                     # breakout at 09:25 while the app was down\n    t = 9 * 60 + 25\n    while t < 10 * 60 + 25:\n        addbar(kite, t // 60, t % 60, 25012, 25015)\n        t += 5\n    run(eng, clock, T(10, 30, 10))\n    r = repo.get(cid)\n    check("L1 breakout from before the restart is NOT traded (late), still ARMED with a note",\n          not rec.inserts and r["status"] == "ARMED" and "late" in (r["note"] or ""), r["note"])\n    addbar(kite, 10, 30, 25015, 24990)\n    addbar(kite, 10, 35, 24990, 25003)\n    run(eng, clock, T(10, 40, 10))\n    check("L2 the next fresh cross trades", len(rec.inserts) == 1)\n\n    clock, kite, repo, mgr, eng, rec, _ = harness()\n    cid = cond(repo, clock, eod="09:30")\n    run(eng, clock, T(9, 30, 2))\n    check("X1 ARMED past its EOD → EXPIRED", repo.get(cid)["status"] == "EXPIRED")\n    old = repo.create((DAY - timedelta(days=1)).isoformat(),\n                      core.validate_condition({"instrument": "NIFTY", "upper": 25000})[0])\n    eng.booted = False\n    eng.tick(clock.t)\n    check("X2 an earlier day\'s ARMED condition expires at boot", repo.get(old)["status"] == "EXPIRED")\n\n\ndef test_restart_resume():\n    print("restart resume / stale")\n    conn = _mem()\n    clock, kite, repo, mgr, eng, rec, _ = harness(conn=conn)\n    cid = cond(repo, clock)\n    set_chain(kite, prices=NIFTY_CE)\n    addbar(kite, 9, 15, 24960, 24990)\n    addbar(kite, 9, 20, 24990, 25012)\n    run(eng, clock, T(9, 25, 8))\n    check("R0 position open", cid in mgr.pos)\n    clock2, kite2, repo2, mgr2, eng2, rec2, _ = harness(conn=conn, start=T(9, 50))\n    set_chain(kite2, prices={(25000, "CE"): 170})\n    kite2.px["NSE:NIFTY 50"] = 25010\n    run(eng2, clock2, T(9, 50, 3))\n    check("R1 a new process adopts the open trade from lvb_conditions (spot stop + target)", cid in mgr2.pos\n          and mgr2.pos[cid].sl_spot == 24975 and mgr2.pos[cid].tp_spot == 25050)\n    kite2.px["NSE:NIFTY 50"] = 24974\n    kite2.px[f"NFO:{sym(\'NIFTY\', 25000, \'CE\')}"] = 120\n    run(eng2, clock2, T(9, 50, 8))\n    check("R2 … and still exits it by the spot SL", repo2.get(cid)["exit_reason"] == "SL")\n\n    conn = _mem()\n    clock, kite, repo, mgr, eng, rec, _ = harness(conn=conn)\n    cid = cond(repo, clock)\n    set_chain(kite, prices=NIFTY_CE)\n    addbar(kite, 9, 15, 24960, 24990)\n    addbar(kite, 9, 20, 24990, 25012)\n    run(eng, clock, T(9, 25, 8))\n    clock2, kite2, repo2, mgr2, eng2, rec2, _ = harness(conn=conn, start=T(9, 20, 0, day_offset=1))\n    run(eng2, clock2, T(9, 20, 2, day_offset=1))\n    check("R3 a prior day\'s open trade → STALE at entry + critical alert", repo2.get(cid)["exit_reason"] == "STALE"\n          and any(a[0] == "STALE_ROW" and a[2].get("severity") == "critical" for a in rec2.alerts))\n\n\ndef test_live():\n    print("LIVE orders")\n    ex = FakeExec()\n    clock, kite, repo, mgr, eng, rec, _ = harness(mode="LIVE", executor=ex)\n    cid = cond(repo, clock)\n    set_chain(kite, prices=NIFTY_CE)\n    addbar(kite, 9, 15, 24960, 24990)\n    addbar(kite, 9, 20, 24990, 25012)\n    run(eng, clock, T(9, 25, 8))\n    r = repo.get(cid)\n    check("V1 LIVE buy at the broker fill 181 (not the quote)", ex.orders[0] == ("BUY", sym("NIFTY", 25000, "CE"), 65)\n          and r["entry_px"] == 181 and r["mode"] == "LIVE" and rec.inserts[0]["trade_mode"] == "LIVE")\n    ex.positions_result = None\n    kite.px["NSE:NIFTY 50"] = 24960\n    kite.px[f"NFO:{sym(\'NIFTY\', 25000, \'CE\')}"] = 100\n    run(eng, clock, T(9, 26, 0))\n    check("V2 SL hit but holdings unreadable → NO sell order, backoff", len(ex.orders) == 1 and cid in mgr.pos)\n    ex.positions_result = [{"tradingsymbol": sym("NIFTY", 25000, "CE"), "quantity": 65}]\n    ex.sell_fill = 99.5\n    run(eng, clock, T(9, 26, 20))\n    check("V3 holdings readable again → sells, books the fill 99.5", ex.orders[-1][0] == "SELL"\n          and repo.get(cid)["exit_px"] == 99.5 and repo.get(cid)["exit_reason"] == "SL")\n\n    ex = FakeExec("AngelOneExecutor")\n    clock, kite, repo, mgr, eng, rec, _ = harness(mode="LIVE", executor=ex)\n    cid = cond(repo, clock, instrument="SENSEX", upper=82000, lower=None)\n    set_chain(kite, inst="SENSEX", exp=date(2026, 10, 29), exch="BFO", prices={(82000, "CE"): 190})\n    addbar(kite, 9, 15, 81960, 81990, token=265)\n    addbar(kite, 9, 20, 81990, 82020, token=265)\n    run(eng, clock, T(9, 25, 8))\n    check("V4 SENSEX LIVE on a non-Zerodha executor → refused, ZERO orders, still ARMED",\n          not ex.orders and repo.get(cid)["status"] == "ARMED" and "EXCHANGE_UNSUPPORTED" in (repo.get(cid)["note"] or ""))\n\n    ex = FakeExec()\n    ex.fill = 190.5\n    clock, kite, repo, mgr, eng, rec, _ = harness(mode="LIVE", executor=ex)\n    cid = cond(repo, clock, instrument="SENSEX", upper=82000, lower=None, lots=2)\n    set_chain(kite, inst="SENSEX", exp=date(2026, 10, 29), exch="BFO", prices={(82000, "CE"): 190})\n    addbar(kite, 9, 15, 81960, 81990, token=265)\n    addbar(kite, 9, 20, 81990, 82020, token=265)\n    run(eng, clock, T(9, 25, 8))\n    r = repo.get(cid)\n    check("V5 SENSEX LIVE on Zerodha: BFO contract, 2 lots × 20 = 40, TP spot 82150",\n          ex.orders == [("BUY", sym("SENSEX", 82000, "CE", date(2026, 10, 29)), 40)] and r["exchange"] == "BFO"\n          and r["tp_spot"] == 82150)\n    ex.positions_result = []\n    out = eng.request_close(cid)\n    check("V6 manual square-off, broker already flat → BROKER_FLAT, nothing sold",\n          out.get("ok") and repo.get(cid)["exit_reason"] == "BROKER_FLAT" and ex.orders[-1][0] == "BUY")\n\n\ndef test_manual_and_kill():\n    print("manual square-off / kill")\n    clock, kite, repo, mgr, eng, rec, _ = harness()\n    a, b = cond(repo, clock), cond(repo, clock, lots=3)\n    set_chain(kite, prices=NIFTY_CE)\n    addbar(kite, 9, 15, 24960, 24990)\n    addbar(kite, 9, 20, 24990, 25012)\n    run(eng, clock, T(9, 25, 8))\n    kite.px[f"NFO:{sym(\'NIFTY\', 25000, \'CE\')}"] = 185\n    out = eng.request_close(a)\n    check("K1 manual square-off one condition @ LTP 185", out.get("exit_price") == 185\n          and repo.get(a)["exit_reason"] == "MANUAL" and b in mgr.pos)\n    res = mgr.kill_adapter()\n    check("K2 kill adapter flattens the rest", res["closed"] == 1 and res["remaining"] == 0\n          and repo.get(b)["exit_reason"] == "KILL")\n    check("K3 3 lots → qty 195", rec.inserts[1]["qty"] == 195)\n\n\ndef test_legacy_and_migration():\n    print("legacy premium-% rows / table migration (LVB_SL_SPOT_20261029)")\n    old_schema = """CREATE TABLE lvb_conditions (\n        id INTEGER PRIMARY KEY AUTOINCREMENT, day TEXT NOT NULL, instrument TEXT NOT NULL, upper REAL, lower REAL,\n        prem_min REAL NOT NULL, prem_max REAL NOT NULL, sl_pct REAL NOT NULL, tp_pts REAL NOT NULL, eod TEXT NOT NULL,\n        lots INTEGER NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER, note TEXT,\n        side TEXT, trigger_bar_ts INTEGER, trigger_close REAL, mode TEXT, symbol TEXT, token INTEGER, exchange TEXT,\n        expiry TEXT, strike REAL, lot_size INTEGER, qty INTEGER, entry_ts INTEGER, entry_px REAL, entry_spot REAL,\n        sl_px REAL, tp_spot REAL, paper_trade_id TEXT, exit_ts INTEGER, exit_px REAL, exit_spot REAL,\n        exit_reason TEXT, mark REAL, mark_spot REAL)"""\n    conn = _mem()\n    conn.execute(old_schema)\n    conn.execute("INSERT INTO lvb_conditions (day, instrument, upper, lower, prem_min, prem_max, sl_pct, tp_pts, eod,"\n                 " lots, status, created_at) VALUES (?, \'NIFTY\', 25000, NULL, 150, 200, 30, 50, \'15:15\', 1, \'ARMED\', ?)",\n                 (DAY.isoformat(), T(9, 0)))\n    clock, kite, repo, mgr, eng, rec, _ = harness(conn=conn)\n    cols = {r[1] for r in repo.conn().execute("PRAGMA table_info(lvb_conditions)").fetchall()}\n    check("M1 an existing old-shape table gains sl_pts + sl_spot in place", {"sl_pts", "sl_spot"} <= cols)\n    new = cond(repo, clock, upper=None, lower=24800)\n    check("M2 new conditions insert fine into the migrated table (sl_pct written 0)",\n          repo.get(new)["sl_pts"] == 25 and repo.get(new)["sl_pct"] == 0)\n    set_chain(kite, prices=NIFTY_CE)\n    addbar(kite, 9, 15, 24960, 24990)\n    addbar(kite, 9, 20, 24990, 25012)\n    run(eng, clock, T(9, 25, 8))\n    r = repo.get(1)\n    check("M3 the legacy row trades with its premium stop (180 × 0.70 = 126), no spot stop",\n          r["status"] == "TRIGGERED" and r["sl_px"] == 126.0 and r["sl_spot"] is None, (r["sl_px"], r["sl_spot"]))\n    kite.px["NSE:NIFTY 50"] = 24950                  # below where a spot stop would be — must NOT matter\n    kite.px[f"NFO:{sym(\'NIFTY\', 25000, \'CE\')}"] = 130\n    run(eng, clock, T(9, 26))\n    check("M4 legacy row ignores spot; holds at LTP 130 > 126", 1 in mgr.pos)\n    kite.px[f"NFO:{sym(\'NIFTY\', 25000, \'CE\')}"] = 125\n    run(eng, clock, T(9, 26, 4))\n    check("M5 … and stops out on the premium (LTP 125 ≤ 126)", repo.get(1)["exit_reason"] == "SL")\n    ok = repo.update_armed(new, core.validate_condition({"instrument": "NIFTY", "lower": 24790, "sl_pts": 40})[0])\n    check("M6 editing stores sl_pts", ok and repo.get(new)["sl_pts"] == 40)\n\n\nif __name__ == "__main__":\n    for fn in (test_core, test_legacy_and_migration, test_paper_ce_tp, test_gap_and_fresh_cross, test_pe_sl_eod, test_skips_stay_armed,\n               test_late_and_expiry, test_restart_resume, test_live, test_manual_and_kill):\n        fn()\n    print(f"\\n{\'ALL PASS\' if not FAILS else f\'{len(FAILS)} FAILED: {FAILS}\'}")\n    sys.exit(1 if FAILS else 0)\n', 'be:api/lvb_routes.py': '# backend/app/api/lvb_routes.py\n#\n# ── LVB_V1_20261023 ── "Tripwire" Levels page API (admin-only: mounted with\n# _require_admin_ui in api_server — experimental feature).\n#\n#   GET    /api/lvb_v1/state              page payload (3 s poll)\n#   POST   /api/lvb_v1/config             {"trade_execution_mode": OFF|PAPER|LIVE|PAPER_LIVE}\n#   POST   /api/lvb_v1/conditions         create (valid for TODAY only)\n#   PUT    /api/lvb_v1/conditions/{id}    edit an ARMED condition (re-arms it from now)\n#   DELETE /api/lvb_v1/conditions/{id}    cancel an ARMED condition\n#   POST   /api/lvb_v1/squareoff/{id}     manual exit of that condition\'s trade\n#   POST   /api/lvb_v1/squareoff_all      manual exit of every open trade\n#\n# ── LVB_SL_SPOT_20261029 ── SL input is sl_pts (spot points from the limit);\n# state carries the per-side spot stops beside the targets.\n#\n# Every handler is wrapped: an LVB fault returns {"ok": False, "error": …}\n# and never a 500 that could disturb the rest of the app.\n\nfrom __future__ import annotations\n\nimport time\nfrom datetime import datetime, timedelta, timezone\nfrom typing import Dict, Optional\n\nfrom fastapi import APIRouter, Body\n\nfrom app.engine.lvb.lvb_core import (STRATEGY_ID, INSTRUMENTS, DEFAULTS, EOD_MAX_ALLOWED, LOTS_MAX,\n                                     validate_condition, describe, minute_of, target_spot, stop_spot)\n\nrouter = APIRouter(prefix="/api/lvb_v1", tags=["LVB_V1"])\nIST = timezone(timedelta(hours=5, minutes=30))\nMODES = ("OFF", "PAPER", "LIVE", "PAPER_LIVE")\n\n\ndef _today() -> str:\n    return datetime.now(IST).date().isoformat()\n\n\ndef _rt():\n    from app.engine.lvb import lvb_runtime as rt\n    return rt\n\n\ndef _spot(inst: str) -> Optional[float]:\n    try:\n        from app.marketdata.market_indices_state import MarketIndicesState\n        v = (MarketIndicesState.snapshot().get(inst) or {}).get("ltp")\n        if v:\n            return float(v)\n    except Exception:\n        pass\n    eng = _rt().get_lvb_engine()\n    if eng is not None and inst in eng.spot:\n        return float(eng.spot[inst][0])\n    return None\n\n\ndef _cfg() -> dict:\n    try:\n        from app.config.strategy_loader import load_strategy_config\n        return load_strategy_config(STRATEGY_ID) or {}\n    except Exception:\n        return {}\n\n\ndef _err(e) -> dict:\n    return {"ok": False, "error": str(e)}\n\n\n@router.get("/state")\ndef lvb_state():\n    try:\n        rt = _rt()\n        repo, mgr, eng = rt.get_lvb_repo(), rt.get_lvb_manager(), rt.get_lvb_engine()\n        day = _today()\n        cfg = _cfg()\n        live = {p["cid"]: p for p in (mgr.positions() if mgr else [])}\n        conds = []\n        for r in repo.for_day(day):\n            r = dict(r)\n            p = live.get(r["id"])\n            if p:\n                r["mark"], r["mark_spot"] = p.get("mark"), p.get("mark_spot")\n            r["open"] = r["status"] == "TRIGGERED" and r.get("exit_ts") is None\n            px = r.get("exit_px") if r.get("exit_ts") else r.get("mark")\n            r["pnl"] = (round((float(px) - float(r["entry_px"])) * int(r["qty"]), 2)\n                        if r.get("entry_px") and px and r.get("qty") else None)\n            if r.get("exit_ts") and mgr is not None and r.get("entry_px"):\n                r["net"] = mgr.net_of(r["entry_px"], r["exit_px"], int(r["qty"]))\n            r["targets"] = {"CE": target_spot("CE", r.get("upper"), None, float(r.get("tp_pts") or 0)),\n                            "PE": target_spot("PE", None, r.get("lower"), float(r.get("tp_pts") or 0))}\n            r["stops"] = {"CE": stop_spot("CE", r.get("upper"), None, r.get("sl_pts")),\n                          "PE": stop_spot("PE", None, r.get("lower"), r.get("sl_pts"))}\n            r["legacy_sl"] = r.get("sl_pts") is None\n            r["summary"] = describe(r)\n            conds.append(r)\n        stale_open = [dict(r) for r in repo.open_trades() if r["day"] != day]\n        return {"ok": True, "strategy": STRATEGY_ID, "running": mgr is not None, "day": day,\n                "mode": str(cfg.get("trade_execution_mode") or "PAPER").upper(),\n                "engine": eng.status() if eng else None,\n                "spot": {k: _spot(k) for k in INSTRUMENTS},\n                "conditions": conds, "stale_open": stale_open,\n                "defaults": {"prem_min": DEFAULTS["prem_min"], "prem_max": DEFAULTS["prem_max"],\n                             "eod": DEFAULTS["eod"], "lots": DEFAULTS["lots"], "lots_max": LOTS_MAX,\n                             "sl_pts": {k: v["sl_default"] for k, v in INSTRUMENTS.items()},\n                             "tp_pts": {k: v["tp_default"] for k, v in INSTRUMENTS.items()}},\n                "server_ts": int(time.time())}\n    except Exception as e:\n        return _err(e)\n\n\n@router.post("/config")\ndef lvb_config(patch: Dict = Body(...)):\n    try:\n        mode = str(patch.get("trade_execution_mode") or "").upper().replace("+", "_")\n        if mode not in MODES:\n            return _err(f"mode must be one of {MODES}")\n        from app.config.strategy_loader import load_strategy_config, save_strategy_config\n        cfg = load_strategy_config(STRATEGY_ID) or {}\n        old = str(cfg.get("trade_execution_mode") or "PAPER").upper()\n        cfg["trade_execution_mode"] = mode\n        save_strategy_config(STRATEGY_ID, cfg)\n        try:\n            from app.event_bus.audit_logger import write_audit_log\n            write_audit_log(f"[LVB][MODE] {old} → {mode} (Levels page)")\n        except Exception:\n            pass\n        return {"ok": True, "mode": mode, "previous": old}\n    except Exception as e:\n        return _err(e)\n\n\ndef _open_for_today(now_min: int) -> Optional[str]:\n    if now_min >= EOD_MAX_ALLOWED:\n        return "today\'s session is over for new conditions (after 15:20)"\n    try:\n        from app.utils.market_hours import is_trading_day\n        if not is_trading_day():\n            return "today is not a trading day"\n    except Exception:\n        pass\n    return None\n\n\n@router.post("/conditions")\ndef lvb_create(body: Dict = Body(...)):\n    try:\n        why = _open_for_today(minute_of(int(time.time())))\n        if why:\n            return _err(why)\n        inst = str(body.get("instrument") or "").upper()\n        clean, err = validate_condition(body, spot=_spot(inst) if inst in INSTRUMENTS else None)\n        if err:\n            return _err(err)\n        nm = minute_of(int(time.time()))\n        from app.engine.lvb.lvb_core import hm_to_min\n        if hm_to_min(clean["eod"]) <= nm:\n            return _err(f"EOD {clean[\'eod\']} has already passed")\n        cid = _rt().get_lvb_repo().create(_today(), clean)\n        try:\n            from app.event_bus.audit_logger import write_audit_log\n            write_audit_log(f"[LVB][CREATE] #{cid} {describe(clean)}")\n        except Exception:\n            pass\n        return {"ok": True, "id": cid}\n    except Exception as e:\n        return _err(e)\n\n\n@router.put("/conditions/{cid}")\ndef lvb_edit(cid: int, body: Dict = Body(...)):\n    try:\n        repo = _rt().get_lvb_repo()\n        cur = repo.get(cid)\n        if not cur or cur["day"] != _today():\n            return _err("no such condition today")\n        if cur["status"] != "ARMED":\n            return _err(f"condition is {cur[\'status\']} — only ARMED conditions can be edited")\n        merged = {**{k: cur.get(k) for k in ("instrument", "upper", "lower", "prem_min", "prem_max", "sl_pts",\n                                              "tp_pts", "eod", "lots")}, **body}\n        inst = str(merged.get("instrument") or "").upper()\n        clean, err = validate_condition(merged, spot=_spot(inst) if inst in INSTRUMENTS else None)\n        if err:\n            return _err(err)\n        if not repo.update_armed(cid, clean):\n            return _err("condition changed state while editing — refresh")\n        try:\n            from app.event_bus.audit_logger import write_audit_log\n            write_audit_log(f"[LVB][EDIT] #{cid} {describe(clean)} (re-armed from now)")\n        except Exception:\n            pass\n        return {"ok": True, "id": cid}\n    except Exception as e:\n        return _err(e)\n\n\n@router.delete("/conditions/{cid}")\ndef lvb_cancel(cid: int):\n    try:\n        repo = _rt().get_lvb_repo()\n        cur = repo.get(cid)\n        if not cur:\n            return _err("no such condition")\n        if cur["status"] != "ARMED":\n            return _err(f"condition is {cur[\'status\']} — only ARMED conditions can be cancelled")\n        if not repo.set_status(cid, "CANCELLED", "cancelled on the Levels page"):\n            return _err("condition changed state — refresh")\n        return {"ok": True, "id": cid}\n    except Exception as e:\n        return _err(e)\n\n\n@router.post("/squareoff/{cid}")\ndef lvb_squareoff(cid: int):\n    try:\n        eng = _rt().get_lvb_engine()\n        if eng is None:\n            return _err("LVB runtime is not running")\n        return eng.request_close(int(cid), "MANUAL")\n    except Exception as e:\n        return _err(e)\n\n\n@router.post("/squareoff_all")\ndef lvb_squareoff_all():\n    try:\n        eng = _rt().get_lvb_engine()\n        if eng is None:\n            return _err("LVB runtime is not running")\n        return {"ok": True, **eng.request_close_all("MANUAL")}\n    except Exception as e:\n        return _err(e)\n', 'fe:pages/LevelBreak.jsx': '// frontend/src/pages/LevelBreak.jsx\n//\n// ── LVB_V1_20261023 ── Levels page ("Tripwire", experimental, admin-only;\n// route + nav in App.jsx). Everything comes from GET /api/lvb_v1/state\n// (3 s poll); every action is one POST/PUT/DELETE and a re-pull.\n//\n//   * Mode — OFF / PAPER / LIVE / PAPER+LIVE for the whole strategy (LIVE is\n//     two-tap). Each trade remembers the book it was taken in.\n//   * New condition — instrument, Upper / Lower spot levels (either or\n//     both), premium band, SL and TP in spot points FROM THE LIMIT, EOD, lots. Valid for today only. Edit re-arms it from now.\n//   * Open trades — live LTP / spot / MTM, per-trade Square off, Square off all\n//     (cards on a phone so Square off is always on screen).\n//   * Today — every condition with its status (ARMED → TRIGGERED / EXPIRED /\n//     CANCELLED), result and the engine\'s last note (skipped breakouts).\n//\n// ── LVB_SL_SPOT_20261029 ──\n//   * No confirm() dialogs anywhere: Tauri\'s webview silently returns false,\n//     so Cancel / Square off / Square off all / Live were dead buttons. Every\n//     destructive action is now TWO-TAP (house pattern: first tap arms for\n//     4 s and relabels "Tap again …", second tap acts).\n//   * SL is spot points from the limit (CE: Upper − SL, PE: Lower + SL).\n\nimport { useCallback, useEffect, useMemo, useRef, useState } from "react";\nimport { getApiBase } from "../api/base";\nimport { useIsMobile } from "../hooks/useIsMobile";\nimport { colors, spacing, typography, pnlStyle, alpha, fonts } from "../tokens";\n\nconst API = () => `${getApiBase()}/api/lvb_v1`;\nconst MODES = [\n  { id: "OFF", label: "Off" },\n  { id: "PAPER", label: "Paper" },\n  { id: "LIVE", label: "Live" },\n  { id: "PAPER_LIVE", label: "Paper + Live" },\n];\nconst INSTS = ["NIFTY", "SENSEX"];\n\nconst inr = (v, d = 0) =>\n  v == null ? "—" : `${v < 0 ? "−" : ""}₹${Math.abs(v).toLocaleString("en-IN", { maximumFractionDigits: d, minimumFractionDigits: d })}`;\nconst n2 = (v, d = 2) => (v == null || v === "" ? "—" : Number(v).toLocaleString("en-IN", { maximumFractionDigits: d }));\nconst istTime = (epoch) =>\n  epoch ? new Date(epoch * 1000).toLocaleTimeString("en-IN", { timeZone: "Asia/Kolkata", hour: "2-digit", minute: "2-digit", hour12: false }) : "—";\n\nasync function call(path, method = "GET", body) {\n  const r = await fetch(`${API()}${path}`, {\n    method,\n    headers: body ? { "Content-Type": "application/json" } : undefined,\n    body: body ? JSON.stringify(body) : undefined,\n  });\n  if (r.status === 403) return { ok: false, error: "admin licence required" };\n  try { return await r.json(); } catch { return { ok: false, error: `HTTP ${r.status}` }; }\n}\n\nconst card = {\n  background: colors.bg.secondary, border: `1px solid ${colors.border.light}`, borderRadius: 10,\n  padding: spacing.lg, marginBottom: spacing.lg,\n};\nconst th = { ...typography.label, color: colors.text.tertiary, textAlign: "left", padding: "6px 8px", whiteSpace: "nowrap" };\nconst td = { ...typography.bodySmall, color: colors.text.primary, padding: "7px 8px", borderTop: `1px solid ${colors.border.dark}`, whiteSpace: "nowrap", verticalAlign: "top" };\nconst mono = { fontFamily: fonts.mono, fontVariantNumeric: "tabular-nums" };\n\nfunction Btn({ children, onClick, tone = "default", disabled, small, title }) {\n  const tones = {\n    default: { bg: colors.bg.tertiary, fg: colors.text.primary, bd: colors.border.light },\n    primary: { bg: colors.primary, fg: "#fff", bd: colors.primary },\n    danger: { bg: alpha(colors.danger, 14), fg: colors.danger, bd: alpha(colors.danger, 45) },\n    ghost: { bg: "transparent", fg: colors.text.secondary, bd: colors.border.light },\n  }[tone];\n  return (\n    <button type="button" onClick={onClick} disabled={disabled} title={title} style={{\n      background: tones.bg, color: tones.fg, border: `1px solid ${tones.bd}`, borderRadius: 7,\n      padding: small ? "3px 9px" : "7px 14px", fontSize: small ? 12 : 13, fontWeight: 600,\n      cursor: disabled ? "not-allowed" : "pointer", opacity: disabled ? 0.5 : 1, fontFamily: "inherit",\n    }}>{children}</button>\n  );\n}\n\nfunction Chip({ text, tone }) {\n  const c = { ARMED: colors.primary, TRIGGERED: colors.warning, OPEN: colors.warning, EXPIRED: colors.text.tertiary,\n              CANCELLED: colors.text.tertiary, CE: colors.profit, PE: colors.loss, LIVE: colors.danger,\n              PAPER: colors.text.secondary, TP: colors.profit, SL: colors.loss }[tone || text] || colors.text.secondary;\n  return (\n    <span style={{ display: "inline-block", padding: "1px 7px", borderRadius: 999, fontSize: 11, fontWeight: 700,\n                   color: c, background: alpha(c, 13), border: `1px solid ${alpha(c, 35)}`, letterSpacing: 0.3 }}>{text}</span>\n  );\n}\n\nfunction Field({ label, children, hint, width = 120 }) {\n  return (\n    <label style={{ display: "flex", flexDirection: "column", gap: 4, minWidth: width, flex: `1 1 ${width}px` }}>\n      <span style={{ ...typography.label, color: colors.text.tertiary }}>{label}</span>\n      {children}\n      {hint && <span style={{ fontSize: 11, color: colors.text.muted }}>{hint}</span>}\n    </label>\n  );\n}\n\nconst inputStyle = {\n  background: colors.bg.input, color: colors.text.primary, border: `1px solid ${colors.border.light}`,\n  borderRadius: 7, padding: "7px 9px", fontSize: 13, fontFamily: "inherit", width: "100%", boxSizing: "border-box",\n};\n\nfunction emptyForm(defaults, inst = "NIFTY") {\n  const d = defaults || {};\n  return {\n    instrument: inst, upper: "", lower: "",\n    prem_min: d.prem_min ?? 150, prem_max: d.prem_max ?? 200,\n    sl_pts: (d.sl_pts || {})[inst] ?? (inst === "SENSEX" ? 75 : 25),\n    tp_pts: (d.tp_pts || {})[inst] ?? (inst === "SENSEX" ? 150 : 50),\n    eod: d.eod || "15:15", lots: d.lots ?? 1,\n  };\n}\n\nexport default function LevelBreak() {\n  const isMobile = useIsMobile();\n  const [st, setSt] = useState(null);\n  const [err, setErr] = useState(null);\n  const [form, setForm] = useState(() => emptyForm(null));\n  const [tpTouched, setTpTouched] = useState(false);\n  const [slTouched, setSlTouched] = useState(false);\n  const [armedKey, setArmedKey] = useState(null);       // two-tap: which action is armed\n  const armTimer = useRef(null);\n  useEffect(() => () => clearTimeout(armTimer.current), []);\n  const twoTap = (key, fn) => {\n    if (armedKey !== key) {\n      setArmedKey(key);\n      clearTimeout(armTimer.current);\n      armTimer.current = setTimeout(() => setArmedKey(null), 4000);\n      return;\n    }\n    clearTimeout(armTimer.current);\n    setArmedKey(null);\n    fn();\n  };\n  const isArmed = (key) => armedKey === key;\n  const [editId, setEditId] = useState(null);\n  const [busy, setBusy] = useState(false);\n  const [msg, setMsg] = useState(null);\n\n  const pull = useCallback(async () => {\n    try {\n      const d = await call("/state");\n      if (d && d.ok) { setSt(d); setErr(null); } else setErr(d?.error || "state unavailable");\n    } catch (e) { setErr(String(e)); }\n  }, []);\n\n  useEffect(() => { pull(); const t = setInterval(pull, 3000); return () => clearInterval(t); }, [pull]);\n\n  const defaults = st?.defaults;\n  const [adopted, setAdopted] = useState(false);   // ── LVB_V1_FIX1_20261023 ── no lint-rule comment needed\n  useEffect(() => {                       // first load: adopt server defaults once (only into an untouched form)\n    if (!defaults || adopted) return;\n    setAdopted(true);\n    setForm((f) => (f.upper === "" && f.lower === "" ? emptyForm(defaults, f.instrument) : f));\n  }, [defaults, adopted]);\n\n  const flash = (text, tone = "ok") => { setMsg({ text, tone }); setTimeout(() => setMsg(null), 6000); };\n\n  const setF = (k, v) => setForm((f) => ({ ...f, [k]: v }));\n  const setInst = (inst) => setForm((f) => ({\n    ...f, instrument: inst,\n    tp_pts: tpTouched ? f.tp_pts : ((defaults?.tp_pts || {})[inst] ?? (inst === "SENSEX" ? 150 : 50)),\n    sl_pts: slTouched ? f.sl_pts : ((defaults?.sl_pts || {})[inst] ?? (inst === "SENSEX" ? 75 : 25)),\n  }));\n\n  const spot = st?.spot?.[form.instrument];\n  const preview = useMemo(() => {\n    const tp = Number(form.tp_pts) || 0;\n    const sl = Number(form.sl_pts) || 0;\n    const out = [];\n    if (form.upper !== "") out.push(`5m close above ${n2(form.upper)} → buy ${form.instrument} CE ₹${form.prem_min}–${form.prem_max}` +\n      (sl > 0 ? ` · SL when spot ≤ ${n2(Number(form.upper) - sl)}` : "") +\n      (tp > 0 ? ` · TP when spot ≥ ${n2(Number(form.upper) + tp)}` : " · no target"));\n    if (form.lower !== "") out.push(`5m close below ${n2(form.lower)} → buy ${form.instrument} PE ₹${form.prem_min}–${form.prem_max}` +\n      (sl > 0 ? ` · SL when spot ≥ ${n2(Number(form.lower) + sl)}` : "") +\n      (tp > 0 ? ` · TP when spot ≤ ${n2(Number(form.lower) - tp)}` : " · no target"));\n    if (out.length) out.push(`Exits fill at the option LTP · square-off ${form.eod} · ${form.lots} lot(s) · first breakout only`);\n    return out;\n  }, [form]);\n\n  async function submit() {\n    setBusy(true);\n    const body = { ...form };\n    ["upper", "lower"].forEach((k) => { if (body[k] === "") body[k] = null; });\n    const d = editId ? await call(`/conditions/${editId}`, "PUT", body) : await call("/conditions", "POST", body);\n    setBusy(false);\n    if (d?.ok) {\n      flash(editId ? `Condition #${editId} updated — re-armed from now` : `Condition #${d.id} armed`);\n      setEditId(null); setTpTouched(false); setSlTouched(false); setForm(emptyForm(defaults, form.instrument)); pull();\n    } else flash(d?.error || "failed", "err");\n  }\n\n  function startEdit(c) {\n    setEditId(c.id); setTpTouched(true); setSlTouched(c.sl_pts != null);\n    setForm({ instrument: c.instrument, upper: c.upper ?? "", lower: c.lower ?? "", prem_min: c.prem_min, prem_max: c.prem_max,\n              sl_pts: c.sl_pts ?? ((defaults?.sl_pts || {})[c.instrument] ?? (c.instrument === "SENSEX" ? 75 : 25)),\n              tp_pts: c.tp_pts, eod: c.eod, lots: c.lots });\n    window.scrollTo({ top: 0, behavior: "smooth" });\n  }\n\n  async function cancelCond(c) {\n    const d = await call(`/conditions/${c.id}`, "DELETE");\n    d?.ok ? flash(`#${c.id} cancelled`) : flash(d?.error || "failed", "err");\n    pull();\n  }\n\n  async function squareOff(c) {\n    const d = await call(`/squareoff/${c.id}`, "POST");\n    d?.ok ? flash(d.queued ? d.message : `#${c.id} squared off @ ${n2(d.exit_price)}`) : flash(d?.error || "failed", "err");\n    pull();\n  }\n\n  async function squareOffAll() {\n    const d = await call("/squareoff_all", "POST");\n    d?.ok ? flash(`closed ${d.closed}${d.queued ? `, ${d.queued} queued (broker deferred)` : ""}`) : flash(d?.error || "failed", "err");\n    pull();\n  }\n\n  async function setMode(m) {\n    if (m === st?.mode) return;\n    const d = await call("/config", "POST", { trade_execution_mode: m });\n    d?.ok ? flash(`Mode: ${m.replace("_", " + ")}`) : flash(d?.error || "failed", "err");\n    pull();\n  }\n\n  const conds = st?.conditions || [];\n  const open = conds.filter((c) => c.open);\n  const hb = st?.engine?.heartbeat_ts;\n  const hbAge = hb && st?.server_ts ? st.server_ts - hb : null;\n  const dayPnl = conds.reduce((s, c) => s + (c.pnl || 0), 0);\n  const traded = conds.filter((c) => c.entry_px != null).length;\n\n  return (\n    <div style={{ padding: isMobile ? spacing.md : spacing.xxl, paddingBottom: isMobile ? 140 : 60, maxWidth: 1280,\n                  margin: "0 auto", fontFamily: fonts.ui, color: colors.text.primary, background: colors.bg.page }}>\n      {/* header */}\n      <div style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: spacing.md, marginBottom: spacing.lg }}>\n        <div style={{ flex: "1 1 260px" }}>\n          <div style={{ ...typography.headingLarge }}>🎯 Levels <span style={{ ...typography.bodySmall, color: colors.text.tertiary }}>· LVB V1 "Tripwire" · experimental</span></div>\n          <div style={{ ...typography.bodySmall, color: colors.text.secondary }}>\n            A 5-minute close through your level buys one option · SL on premium · TP on spot · flat by your EOD\n          </div>\n        </div>\n        <div style={{ display: "flex", gap: spacing.md, alignItems: "center", flexWrap: "wrap" }}>\n          {INSTS.map((k) => (\n            <span key={k} style={{ ...typography.bodySmall, color: colors.text.secondary }}>\n              {k} <b style={{ ...mono, color: colors.text.primary }}>{n2(st?.spot?.[k])}</b>\n            </span>\n          ))}\n          <span title="engine heartbeat" style={{ ...typography.bodySmall, color: !st?.running ? colors.danger : hbAge != null && hbAge > 10 ? colors.warning : colors.success }}>\n            ● {!st?.running ? "runtime not running" : hbAge == null ? "idle (outside session)" : hbAge > 10 ? `stale ${hbAge}s` : "live"}\n          </span>\n        </div>\n      </div>\n\n      {/* mode */}\n      <div style={{ ...card, display: "flex", flexWrap: "wrap", gap: spacing.md, alignItems: "center" }}>\n        <span style={{ ...typography.label, color: colors.text.tertiary }}>Mode</span>\n        <div style={{ display: "flex", gap: 4, flexWrap: "wrap" }}>\n          {MODES.map((m) => (\n            <Btn key={m.id} small\n                 tone={st?.mode === m.id ? (m.id.includes("LIVE") ? "danger" : "primary") : isArmed(`mode:${m.id}`) ? "danger" : "ghost"}\n                 title={m.id.includes("LIVE") ? "Real orders at the broker — tap twice" : undefined}\n                 onClick={() => (m.id.includes("LIVE") && st?.mode !== m.id\n                   ? twoTap(`mode:${m.id}`, () => setMode(m.id)) : setMode(m.id))}>\n              {isArmed(`mode:${m.id}`) ? `Tap again → ${m.label} (real orders)` : m.label}\n            </Btn>\n          ))}\n        </div>\n        <span style={{ ...typography.bodySmall, color: colors.text.tertiary, flex: "1 1 300px" }}>\n          {st?.mode === "OFF" ? "No new entries; open trades are still managed to their exit."\n            : (st?.mode || "").includes("LIVE") ? "LIVE: real orders. SL / TP / EOD are engine exits — there is no stop at the broker while the app is closed."\n            : "Paper fills at the LTP right after the 5m close."}\n        </span>\n        <span style={{ ...typography.bodySmall, color: colors.text.secondary }}>\n          Today: {traded} trade(s) · <span style={pnlStyle(dayPnl)}>{inr(dayPnl)}</span> gross\n        </span>\n      </div>\n\n      {err && <div style={{ ...card, borderColor: alpha(colors.danger, 50), color: colors.danger }}>Backend: {err}</div>}\n      {msg && <div style={{ ...card, padding: spacing.md, borderColor: msg.tone === "err" ? alpha(colors.danger, 50) : alpha(colors.success, 50),\n                            color: msg.tone === "err" ? colors.danger : colors.success }}>{msg.text}</div>}\n      {(st?.stale_open || []).length > 0 && (\n        <div style={{ ...card, borderColor: alpha(colors.danger, 50), color: colors.danger }}>\n          {st.stale_open.length} trade(s) from an earlier day are still open — the engine closes them as STALE at its next session start. Verify the broker book.\n        </div>\n      )}\n\n      {/* form */}\n      <div style={card}>\n        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: spacing.md }}>\n          <div style={{ ...typography.headingSmall }}>{editId ? `Edit condition #${editId}` : "New condition (today only)"}</div>\n          <div style={{ display: "flex", gap: 4 }}>\n            {INSTS.map((k) => (\n              <Btn key={k} small tone={form.instrument === k ? "primary" : "ghost"} onClick={() => setInst(k)}>{k}</Btn>\n            ))}\n          </div>\n        </div>\n        <div style={{ display: "flex", flexWrap: "wrap", gap: spacing.md }}>\n          <Field label="Upper limit (spot)" hint={spot ? `spot ${n2(spot)}` : "CE side"} width={140}>\n            <input style={{ ...inputStyle, ...mono }} inputMode="decimal" value={form.upper} placeholder="e.g. 25000"\n                   onChange={(e) => setF("upper", e.target.value)} />\n          </Field>\n          <Field label="Lower limit (spot)" hint="PE side" width={140}>\n            <input style={{ ...inputStyle, ...mono }} inputMode="decimal" value={form.lower} placeholder="e.g. 24800"\n                   onChange={(e) => setF("lower", e.target.value)} />\n          </Field>\n          <Field label="Premium min ₹" width={100}>\n            <input style={{ ...inputStyle, ...mono }} inputMode="decimal" value={form.prem_min} onChange={(e) => setF("prem_min", e.target.value)} />\n          </Field>\n          <Field label="Premium max ₹" width={100}>\n            <input style={{ ...inputStyle, ...mono }} inputMode="decimal" value={form.prem_max} onChange={(e) => setF("prem_max", e.target.value)} />\n          </Field>\n          <Field label="SL spot pts" hint="from the limit" width={100}>\n            <input style={{ ...inputStyle, ...mono }} inputMode="decimal" value={form.sl_pts}\n                   onChange={(e) => { setSlTouched(true); setF("sl_pts", e.target.value); }} />\n          </Field>\n          <Field label="TP spot pts" hint="from the limit · 0 = none" width={110}>\n            <input style={{ ...inputStyle, ...mono }} inputMode="decimal" value={form.tp_pts}\n                   onChange={(e) => { setTpTouched(true); setF("tp_pts", e.target.value); }} />\n          </Field>\n          <Field label="EOD" hint="09:20–15:20" width={100}>\n            <input style={{ ...inputStyle, ...mono }} type="time" min="09:20" max="15:20" value={form.eod} onChange={(e) => setF("eod", e.target.value)} />\n          </Field>\n          <Field label="Lots" width={70}>\n            <input style={{ ...inputStyle, ...mono }} inputMode="numeric" value={form.lots} onChange={(e) => setF("lots", e.target.value)} />\n          </Field>\n        </div>\n        {preview.length > 0 && (\n          <ul style={{ margin: `${spacing.md}px 0 0`, paddingLeft: 18, ...typography.bodySmall, color: colors.text.secondary }}>\n            {preview.map((p) => <li key={p}>{p}</li>)}\n          </ul>\n        )}\n        <div style={{ display: "flex", gap: spacing.sm, marginTop: spacing.md }}>\n          <Btn tone="primary" disabled={busy || (form.upper === "" && form.lower === "")} onClick={submit}>\n            {editId ? "Save changes" : "Arm condition"}\n          </Btn>\n          {editId && <Btn tone="ghost" onClick={() => { setEditId(null); setTpTouched(false); setSlTouched(false); setForm(emptyForm(defaults, form.instrument)); }}>Cancel edit</Btn>}\n        </div>\n      </div>\n\n      {/* open trades */}\n      {open.length > 0 && (\n        <div style={card}>\n          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: spacing.sm }}>\n            <div style={{ ...typography.headingSmall }}>Open trades ({open.length})</div>\n            <Btn tone="danger" small onClick={() => twoTap("sqall", squareOffAll)}>\n              {isArmed("sqall") ? "Tap again: square off ALL" : "Square off all"}\n            </Btn>\n          </div>\n          {isMobile ? (\n            <div style={{ display: "flex", flexDirection: "column", gap: spacing.sm }}>\n              {open.map((c) => (\n                <div key={c.id} style={{ border: `1px solid ${colors.border.light}`, borderRadius: 8, padding: spacing.md, background: colors.bg.tertiary }}>\n                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", gap: spacing.sm }}>\n                    <span style={{ ...mono, fontSize: 13 }}><Chip text={c.side} /> {c.symbol}</span>\n                    <span style={{ ...mono, fontSize: 15, ...pnlStyle(c.pnl) }}>{inr(c.pnl)}</span>\n                  </div>\n                  <div style={{ display: "grid", gridTemplateColumns: "repeat(3, 1fr)", gap: 6, marginTop: spacing.sm, fontSize: 12, color: colors.text.secondary }}>\n                    <span>Entry <b style={mono}>{n2(c.entry_px)}</b></span>\n                    <span>LTP <b style={mono}>{n2(c.mark)}</b></span>\n                    <span>SL <b style={{ ...mono, color: colors.loss }}>{c.sl_spot != null ? n2(c.sl_spot) : `₹${n2(c.sl_px)}`}</b></span>\n                    <span>Spot <b style={mono}>{n2(c.mark_spot)}</b></span>\n                    <span>TP <b style={{ ...mono, color: colors.profit }}>{c.tp_spot == null ? "none" : n2(c.tp_spot)}</b></span>\n                    <span>EOD <b style={mono}>{c.eod}</b></span>\n                  </div>\n                  <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginTop: spacing.sm }}>\n                    <span style={{ fontSize: 11, color: colors.text.tertiary }}>#{c.id} · <Chip text={c.mode} /> · {c.qty} qty · in {istTime(c.entry_ts)}</span>\n                    <Btn tone="danger" small onClick={() => twoTap(`sq:${c.id}`, () => squareOff(c))}>\n                      {isArmed(`sq:${c.id}`) ? "Tap again to square off" : "Square off"}\n                    </Btn>\n                  </div>\n                </div>\n              ))}\n            </div>\n          ) : (\n          <div style={{ overflowX: "auto" }}>\n            <table style={{ width: "100%", borderCollapse: "collapse" }}>\n              <thead><tr>{["#", "Side", "Contract", "Book", "Entry", "LTP", "SL spot", "Spot", "TP spot", "MTM", "EOD", ""].map((h) => <th key={h} style={th}>{h}</th>)}</tr></thead>\n              <tbody>\n                {open.map((c) => (\n                  <tr key={c.id}>\n                    <td style={td}>{c.id}</td>\n                    <td style={td}><Chip text={c.side} /></td>\n                    <td style={{ ...td, ...mono }}>{c.symbol}<div style={{ fontSize: 11, color: colors.text.tertiary }}>{c.qty} qty · in {istTime(c.entry_ts)}</div></td>\n                    <td style={td}><Chip text={c.mode} /></td>\n                    <td style={{ ...td, ...mono }}>{n2(c.entry_px)}</td>\n                    <td style={{ ...td, ...mono }}>{n2(c.mark)}</td>\n                    <td style={{ ...td, ...mono, color: colors.loss }}>{c.sl_spot != null ? n2(c.sl_spot) : `₹${n2(c.sl_px)}`}</td>\n                    <td style={{ ...td, ...mono }}>{n2(c.mark_spot)}</td>\n                    <td style={{ ...td, ...mono, color: colors.profit }}>{c.tp_spot == null ? "none" : n2(c.tp_spot)}</td>\n                    <td style={{ ...td, ...mono, ...pnlStyle(c.pnl) }}>{inr(c.pnl)}</td>\n                    <td style={{ ...td, ...mono }}>{c.eod}</td>\n                    <td style={td}><Btn tone="danger" small onClick={() => twoTap(`sq:${c.id}`, () => squareOff(c))}>\n                      {isArmed(`sq:${c.id}`) ? "Tap again to square off" : "Square off"}\n                    </Btn></td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n          )}\n        </div>\n      )}\n\n      {/* today */}\n      <div style={card}>\n        <div style={{ ...typography.headingSmall, marginBottom: spacing.sm }}>Today · {st?.day || "—"} ({conds.length})</div>\n        {conds.length === 0 ? (\n          <div style={{ ...typography.bodySmall, color: colors.text.tertiary }}>No conditions yet. Armed conditions are checked on every 5-minute close until their EOD.</div>\n        ) : (\n          <div style={{ overflowX: "auto" }}>\n            <table style={{ width: "100%", borderCollapse: "collapse" }}>\n              <thead><tr>{["#", "Inst", "Upper → CE", "Lower → PE", "Band ₹", "SL", "EOD", "Lots", "Status", "Trade", "Result", "Note", ""].map((h) => <th key={h} style={th}>{h}</th>)}</tr></thead>\n              <tbody>\n                {conds.slice().reverse().map((c) => (\n                  <tr key={c.id} style={{ opacity: ["EXPIRED", "CANCELLED"].includes(c.status) ? 0.6 : 1 }}>\n                    <td style={td}>{c.id}<div style={{ fontSize: 11, color: colors.text.tertiary }}>{istTime(c.created_at)}</div></td>\n                    <td style={td}>{c.instrument}</td>\n                    <td style={{ ...td, ...mono }}>{c.upper == null ? "—" : n2(c.upper)}\n                      {c.stops?.CE != null && <div style={{ fontSize: 11, color: colors.loss }}>SL {n2(c.stops.CE)}</div>}\n                      {c.targets?.CE != null && <div style={{ fontSize: 11, color: colors.profit }}>TP {n2(c.targets.CE)}</div>}</td>\n                    <td style={{ ...td, ...mono }}>{c.lower == null ? "—" : n2(c.lower)}\n                      {c.stops?.PE != null && <div style={{ fontSize: 11, color: colors.loss }}>SL {n2(c.stops.PE)}</div>}\n                      {c.targets?.PE != null && <div style={{ fontSize: 11, color: colors.profit }}>TP {n2(c.targets.PE)}</div>}</td>\n                    <td style={{ ...td, ...mono }}>{n2(c.prem_min, 0)}–{n2(c.prem_max, 0)}</td>\n                    <td style={{ ...td, ...mono }}>{c.legacy_sl ? `${n2(c.sl_pct, 1)}% (old)` : `${n2(c.sl_pts, 0)} pts`}</td>\n                    <td style={{ ...td, ...mono }}>{c.eod}</td>\n                    <td style={{ ...td, ...mono }}>{c.lots}</td>\n                    <td style={td}><Chip text={c.open ? "OPEN" : c.status} /></td>\n                    <td style={{ ...td, ...mono }}>{c.symbol ? <>\n                      <Chip text={c.side} /> {c.symbol}\n                      <div style={{ fontSize: 11, color: colors.text.tertiary }}>{c.mode} · {istTime(c.entry_ts)} @ {n2(c.entry_px)}{c.exit_ts ? ` → ${istTime(c.exit_ts)} @ ${n2(c.exit_px)}` : ""}</div>\n                    </> : "—"}</td>\n                    <td style={{ ...td, ...mono }}>{c.entry_px != null ? <>\n                      <span style={pnlStyle(c.pnl)}>{inr(c.pnl)}</span>\n                      {c.exit_reason && <div><Chip text={c.exit_reason} /></div>}\n                      {c.net != null && <div style={{ fontSize: 11, color: colors.text.tertiary }}>net {inr(c.net)}</div>}\n                    </> : "—"}</td>\n                    <td style={{ ...td, whiteSpace: "normal", minWidth: 150, maxWidth: 240, color: colors.text.secondary }}>{c.note || ""}</td>\n                    <td style={td}>\n                      {c.status === "ARMED" && <div style={{ display: "flex", gap: 4 }}>\n                        <Btn small onClick={() => startEdit(c)}>Edit</Btn>\n                        <Btn small tone={isArmed(`cancel:${c.id}`) ? "danger" : "ghost"}\n                             onClick={() => twoTap(`cancel:${c.id}`, () => cancelCond(c))}>\n                          {isArmed(`cancel:${c.id}`) ? "Tap again to cancel" : "Cancel"}\n                        </Btn>\n                      </div>}\n                      {c.open && <Btn small tone="danger" onClick={() => twoTap(`sq:${c.id}`, () => squareOff(c))}>\n                        {isArmed(`sq:${c.id}`) ? "Tap again to square off" : "Square off"}\n                      </Btn>}\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n        )}\n        <div style={{ ...typography.bodySmall, color: colors.text.muted, marginTop: spacing.md }}>\n          Rules: the 5m close must cross the level fresh (previous close inside; the day\'s first candle uses its open, so a gap beyond the level never triggers).\n          A breakout that can\'t be traded (no strike in the band, judged late after a restart, already past the target, mode Off) leaves the condition armed with a note.\n          Only a filled entry uses the condition up.\n        </div>\n      </div>\n    </div>\n  );\n}\n'}
