async def call(method, path, body=None):
    raw = json.dumps(body).encode() if body is not None else b""
    scope = {"type": "http", "asgi": {"version": "3.0"}, "http_version": "1.1", "method": method, "scheme": "http",
             "path": path, "raw_path": path.encode(), "query_string": b"", "root_path": "",
             "headers": [(b"content-type", b"application/json"), (b"content-length", str(len(raw)).encode())],
             "client": ("127.0.0.1", 1), "server": ("127.0.0.1", 80)}
    sent = {"body": b""}; got = [False]
    async def receive():
        if not got[0]:
            got[0] = True; return {"type": "http.request", "body": raw, "more_body": False}
        return {"type": "http.disconnect"}
    async def send(m):
        if m["type"] == "http.response.start": sent["status"] = m["status"]
        elif m["type"] == "http.response.body": sent["body"] += m.get("body", b"")
    await app(scope, receive, send)
    return sent["status"], json.loads(sent["body"] or b"null")
