def _missing_dep(text):
    for ln in (text or "").splitlines():
        if "ModuleNotFoundError" in ln and "'app" not in ln:
            return ln.strip()
    return None


def run_py(tmp, arg, label, is_file=False):
    home = os.path.join(tmp, "home")
    os.makedirs(home, exist_ok=True)
    env = dict(os.environ, PYTHONPATH=os.path.join(tmp, "backend"), SCALP_APP_HOME=home, HOME=home)
    p = subprocess.run([sys.executable, arg] if is_file else [sys.executable, "-c", arg],
                       cwd=os.path.join(tmp, "backend"), capture_output=True, text=True, timeout=600, env=env)
    out = (p.stdout or "") + (p.stderr or "")
    if p.returncode != 0:
        dep = _missing_dep(out)
        if dep:
            print(f"   note: {label} skipped here — {dep} (run before delivery)")
            return
        print(out[-4000:])
        die(f"{label} failed")
    tail = [ln for ln in out.splitlines() if ln.strip()][-1:]
    print(f"   {label}: {tail[0] if tail else 'ok'}")


def main():
    if not os.path.isdir("backend/app") or not os.path.isdir("frontend/src"):
        die("run from the repo root")
    targets = []
    for key in NEW:
        kind, rel = key.split(":", 1)
        for tree in (BE_TREES if kind == "be" else FE_TREES):
            if os.path.isdir(tree):
                targets.append((key, os.path.join(tree, rel)))
    staged, done = {}, 0
    for key, path in targets:
        if not os.path.isfile(path):
            die(f"{path} missing — LVB_V1 not applied in this tree?")
        cur = open(path, "rb").read()
        if cur.decode("utf-8") == NEW[key]:
            done += 1
            continue
        if sha(cur) != PREV_SHA[key]:
            die(f"{path} is not the delivered LVB_V1 version (hand-edited?). Restore it with "
                f"'git checkout -- {path}' if the change isn't needed, then re-run ONLY this script")
        staged[path] = (cur.decode("utf-8"), NEW[key])
    if not staged:
        print(f"[{FENCE}] already applied — nothing to do.")
        return
    if done:
        die(f"mixed state: {done} file(s) already new, {len(staged)} old — partial manual copy?")
    try:
        out = subprocess.run(["git", "status", "--porcelain", "--"] + [p for p in staged if not p.startswith("desktop/")],
                             capture_output=True, text=True, timeout=20).stdout.strip()
        if out:
            die("uncommitted changes on files this script replaces:\n   " + out.replace("\n", "\n   "))
    except FileNotFoundError:
        print("   note: git not found — skipping working-copy check")
    for path, (_, new) in staged.items():
        if path.endswith(".py"):
            with tempfile.NamedTemporaryFile("w", suffix=".py", delete=False, encoding="utf-8") as tf:
                tf.write(new)
            try:
                py_compile.compile(tf.name, doraise=True)
            except py_compile.PyCompileError as e:
                die(f"{path} does not compile: {e}")
            finally:
                os.unlink(tf.name)
    print(f"[{FENCE}] py_compile OK")
    tmp = tempfile.mkdtemp(prefix="lvb_slspot_")
    try:
        dst = os.path.join(tmp, "backend", "app")
        shutil.copytree("backend/app", dst, ignore=shutil.ignore_patterns("*.bak-*", "__pycache__", "*.pyc", "*.db"))
        for path, (_, new) in staged.items():
            if path.startswith("backend/app/"):
                with open(os.path.join(dst, path[len("backend/app/"):]), "w", encoding="utf-8") as f:
                    f.write(new)
        print(f"[{FENCE}] behavioural suite (spot SL, legacy rows, old-table migration, all earlier cases)")
        run_py(tmp, os.path.join(dst, "engine", "lvb", "test_lvb.py"), "LVB suite", is_file=True)
        print(f"[{FENCE}] routes via a hand-built ASGI scope")
        run_py(tmp, ROUTE_TEST, "routes")
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    for path, (old, new) in staged.items():
        with open(f"{path}.bak-{FENCE}", "w", encoding="utf-8") as f:
            f.write(old)
        with open(path, "w", encoding="utf-8") as f:
            f.write(new)
        print(f"   wrote {path}")
    print(f"\n[{FENCE}] DONE — {len(staged)} file(s), backups *.bak-{FENCE}.")
    print("Next: ./desktop/build-scalp.sh, restart. Cancel / Square off / Live are now two-tap.")


if __name__ == "__main__":
    main()
